using System.Runtime.CompilerServices;
using CIS.Logging.Events;

namespace CIS.Logging;

/// <summary>Captures C# interpolation arguments for owned, bounded logging.</summary>
/// <remarks>Expressions execute on the caller, including when the level is disabled. Built-in
/// scalars are formatted by the consumer using invariant culture. User-defined formatting runs
/// at most once on the caller; only its copied text is retained. This handler does not derive
/// structured attribute names from expressions.</remarks>
[InterpolatedStringHandler]
public struct LogInterpolatedStringHandler
{
    private InterpolationCapture? capture;

    /// <summary>Starts a bounded capture; compiler size hints never determine allocation size.</summary>
    public LogInterpolatedStringHandler(int literalLength, int formattedCount)
    {
        capture = new InterpolationCapture();
    }

    /// <summary>Captures literal text.</summary>
    public void AppendLiteral(string value) => Capture.AddLiteral(value);

    /// <summary>Captures an interpolation expression.</summary>
    public void AppendFormatted<T>(T value) => Capture.AddValue(value, 0, null);

    /// <summary>Captures an expression and its .NET format string.</summary>
    public void AppendFormatted<T>(T value, string? format) => Capture.AddValue(value, 0, format);

    /// <summary>Captures an expression and alignment.</summary>
    public void AppendFormatted<T>(T value, int alignment) => Capture.AddValue(value, alignment, null);

    /// <summary>Captures an expression, alignment and .NET format string.</summary>
    public void AppendFormatted<T>(T value, int alignment, string? format) => Capture.AddValue(value, alignment, format);

    /// <summary>Captures nullable string text, alignment and optional format metadata.</summary>
    public void AppendFormatted(string? value, int alignment = 0, string? format = null) => Capture.AddValue(value, alignment, format);

    /// <summary>Copies a span immediately; no borrowed memory is retained.</summary>
    public void AppendFormatted(ReadOnlySpan<char> value, int alignment = 0, string? format = null) => Capture.AddSpan(value, alignment, format);

    private InterpolationCapture Capture => capture ??= new InterpolationCapture();
    internal CapturedInterpolation Freeze() => Capture.Freeze();
}

namespace CIS.Logging.Runtime;

// Sole-consumer metadata: sorting never moves physical slots or changes an event's creation key.
internal sealed class IncomingBatchIndex(int capacity)
{
    private readonly Entry[] entries = new Entry[capacity];
    internal int Count { get; private set; }

    internal void Capture(IncomingRingBuffer ring)
    {
        Release();
        for (int slot = 0; slot < ring.Capacity; slot++)
        {
            if (ring.Read(slot) is { } item) { entries[Count++] = new(slot, item); }
        }
        Array.Sort(entries, 0, Count, EntryComparer.Instance);
    }

    internal Entry At(int index) => entries[index];
    internal void Clear(int index) => entries[index] = default;
    internal void Release()
    {
        Array.Clear(entries, 0, Count);
        Count = 0;
    }

    internal readonly record struct Entry(int Slot, IncomingEvent? Item);
    private sealed class EntryComparer : IComparer<Entry>
    {
        internal static readonly EntryComparer Instance = new();
        public int Compare(Entry first, Entry second)
        {
            int age = first.Item!.CreationTimestamp.CompareTo(second.Item!.CreationTimestamp);
            return age == 0 ? first.Slot.CompareTo(second.Slot) : age;
        }
    }
}

using CIS.Logging.Events;

namespace CIS.Logging.Runtime;

// Producers own no slot before the final exchange. Only the consumer claims/removes waiting events.
internal sealed class IncomingRingBuffer
{
    private readonly IncomingEvent?[] slots;
    private readonly int[] budgets;
    private readonly AtomicLogCounter admitted = new(), consumed = new(), evicted = new(), abandoned = new();
    private readonly AtomicLogCounter[] evictedByLevel = Enumerable.Range(0, 6).Select(_ => new AtomicLogCounter()).ToArray();
    private long cursor = -1, publishers, waiting;
    private int closed;

    internal IncomingRingBuffer(int capacity, LoggingOptions options)
    {
        if (capacity is < LoggingOptions.MinimumQueueCapacity or > LoggingOptions.MaximumQueueCapacity)
        { throw new ArgumentOutOfRangeException(nameof(capacity)); }
        ArgumentNullException.ThrowIfNull(options);
        options.ValidateIncomingSettings();
        slots = new IncomingEvent?[capacity];
        int?[] overrides = [options.IncomingTraceScanPercentage, options.IncomingDebugScanPercentage,
            options.IncomingInformationScanPercentage, options.IncomingWarningScanPercentage,
            options.IncomingErrorScanPercentage, options.IncomingCriticalScanPercentage];
        budgets = new int[6];
        int fallback = options.IncomingScanPercentage;
        for (int level = 0; level < budgets.Length; level++)
        { budgets[level] = Math.Max(1, (capacity * (overrides[level] ?? fallback) + 99) / 100); }
    }

    internal int Capacity => slots.Length;
    internal bool IsClosed => Volatile.Read(ref closed) != 0;
    internal long ActivePublishers => Interlocked.Read(ref publishers);
    internal int Budget(CoreLogLevel level) => budgets[(int)level];

    internal IncomingAdmission TryPublish(IncomingEvent? item, out IncomingPublication publication)
    {
        publication = default;
        if (item is null || item.Facts is null || item.Level is < CoreLogLevel.Trace or > CoreLogLevel.Critical)
        { return IncomingAdmission.Invalid; }
        if (!TryEnterPublisher()) { return IncomingAdmission.Stopped; }
        try
        {
            int index = SelectSlot(item, out int probes);
            publication = Exchange(index, item, probes);
            return IncomingAdmission.Accepted;
        }
        finally { ExitPublisher(); }
    }

    // Fixed steps are also exercised individually by controlled native races; no caller callback seam.
    internal bool TryEnterPublisher()
    {
        if (IsClosed) { return false; }
        Interlocked.Increment(ref publishers);
        if (!IsClosed) { return true; }
        ExitPublisher();
        return false;
    }

    internal void ExitPublisher() => Interlocked.Decrement(ref publishers);
    internal void Close() => Interlocked.Exchange(ref closed, 1);

    internal int SelectSlot(IncomingEvent item, out int probes)
    {
        int index = (int)(unchecked((ulong)Interlocked.Increment(ref cursor)) % (ulong)slots.Length);
        int selected = index;
        IncomingEvent? candidate = null;
        int limit = budgets[(int)item.Level];
        probes = 0;
        for (int offset = 0; offset < limit; offset++)
        {
            probes++;
            IncomingEvent? observed = Volatile.Read(ref slots[index]);
            if (observed is null) { return index; }
            if (candidate is null || observed.Level < candidate.Level ||
                observed.Level == candidate.Level && observed.CreationTimestamp < candidate.CreationTimestamp)
            { selected = index; candidate = observed; }
            if (++index == slots.Length) { index = 0; }
        }
        return selected;
    }

    internal IncomingPublication Exchange(int index, IncomingEvent item, int probes)
    {
        IncomingEvent? displaced = Interlocked.Exchange(ref slots[index], item);
        admitted.Increment();
        if (displaced is null) { Interlocked.Increment(ref waiting); }
        else
        {
            evicted.Increment();
            evictedByLevel[(int)displaced.Level].Increment();
        }
        return new(index, probes, displaced);
    }

    internal IncomingEvent? Read(int index) => Volatile.Read(ref slots[index]);

    internal bool TryClaim(int index, IncomingEvent expected)
    {
        if (!ReferenceEquals(Interlocked.CompareExchange(ref slots[index], null, expected), expected)) { return false; }
        consumed.Increment();
        Interlocked.Decrement(ref waiting);
        return true;
    }

    // Only the sole consumer/cleanup coordinator calls this, never a producer or a timer callback.
    internal IncomingEvent? AbandonSlot(int index)
    {
        IncomingEvent? removed = Interlocked.Exchange(ref slots[index], null);
        if (removed is not null) { abandoned.Increment(); Interlocked.Decrement(ref waiting); }
        return removed;
    }

    internal long EvictedAt(CoreLogLevel level) => evictedByLevel[(int)level].Value;

    internal bool TryAbandon(int index, IncomingEvent expected)
    {
        if (!ReferenceEquals(Interlocked.CompareExchange(ref slots[index], null, expected), expected)) { return false; }
        abandoned.Increment(); Interlocked.Decrement(ref waiting);
        return true;
    }

    internal IncomingRingSnapshot Capture() => new(admitted.Value, consumed.Value, evicted.Value, abandoned.Value,
        Math.Clamp(Interlocked.Read(ref waiting), 0, slots.Length), ActivePublishers,
        admitted.IsSaturated || consumed.IsSaturated || evicted.IsSaturated || abandoned.IsSaturated);
}

internal enum IncomingAdmission { Accepted, Stopped, Invalid }
internal readonly record struct IncomingPublication(int Slot, int Probes, IncomingEvent? Displaced);
// Independent atomic reads: a live snapshot is deliberately not a coherent lifetime cut.
internal readonly record struct IncomingRingSnapshot(long Admitted, long Consumed, long Evicted, long Abandoned,
    long Waiting, long ActivePublishers, bool IsSaturated);

internal sealed record IncomingEvent(long Sequence, CoreLogLevel Level, CapturedEventFacts Facts)
{
    internal long CreationTimestamp => Facts.TimestampUtc.UtcTicks;
}

using System.Collections.Concurrent;
using System.Text;
using CIS.Logging;
using CIS.Logging.Runtime;
using CIS.TestSupport;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace CIS.Tests.UnitTests;

[TestClass]
public sealed class CommonWriterPipelineTests
{
    [TestMethod]
    [DataRow(LogOutputFormat.JsonLines, false)]
    [DataRow(LogOutputFormat.Human, false)]
    [DataRow(LogOutputFormat.JsonLines, true)]
    [DataRow(LogOutputFormat.Human, true)]
    public async Task BuiltInAndApplicationWritersShareDrainAndIsolateFailure(LogOutputFormat format, bool fail)
    {
        using var directory = new TemporaryDirectory();
        using var console = new MemoryStream();
        var writer = new Writer(fail);
        string path = Path.Combine(directory.Path, "combined.log");
        await using var runtime = QueuedRuntimeFactory.CreateConfiguredQueued(new EventMetadata(), new LoggingOptions
        {
            ConsoleLevel = CoreLogLevel.Information,
            FileLevel = CoreLogLevel.Information,
            ConsoleFormat = format,
            FileFormat = format,
            FilePath = path,
            QueueCapacity = 8
        }, acquireConsole: _ => console, writers: [new("application", writer, ownsWriter: true)], incomingPipeline: true);
        var accepted = runtime.CreateLogger("Mixed").Write(CoreLogLevel.Warning,
            new LogEventData { EventName = "mixed.writer", Message = "shared-message" });
        Assert.AreEqual(1L, accepted.IncomingSequence);
        var stopped = await runtime.StopAsync(CancellationToken.None).WaitAsync(TimeSpan.FromSeconds(10));
        Assert.AreEqual(!fail, stopped.Succeeded);
        Assert.AreEqual(1L, stopped.Incoming!.Processed);
        foreach (string name in new[] { "console", "file" })
        { Assert.AreEqual(1L, stopped.Outputs.Single(output => output.OutputName == name).Written); }
        CollectionAssert.AreEqual(console.ToArray(), File.ReadAllBytes(path));
        StringAssert.Contains(Encoding.UTF8.GetString(console.ToArray()), "shared-message");
        Assert.IsTrue(console.CanWrite, "The console stream remains borrowed after shutdown.");
        Assert.AreEqual(1, writer.Disposals);
        if (fail)
        {
            Assert.AreEqual(1L, stopped.Outputs.Single(output => output.OutputName == "application").Failed);
            await Assert.ThrowsExactlyAsync<IOException>(() => runtime.Completion);
        }
        else
        {
            await runtime.Completion;
            if (format == LogOutputFormat.JsonLines)
            { Assert.AreEqual(writer.Lines.Single(), Encoding.UTF8.GetString(console.ToArray())); }
            else { StringAssert.StartsWith(writer.Lines.Single(), "{"); }
        }
    }

    private sealed class Writer(bool fail) : ILogWriter
    {
        internal ConcurrentQueue<string> Lines { get; } = new();
        internal int Disposals;
        public ValueTask WriteAsync(string jsonLine, CancellationToken cancellationToken)
        {
            if (fail) { throw new IOException("controlled application writer fault"); }
            Lines.Enqueue(jsonLine); return ValueTask.CompletedTask;
        }
        public ValueTask FlushAsync(CancellationToken cancellationToken) => ValueTask.CompletedTask;
        public ValueTask DisposeAsync() { Disposals++; return ValueTask.CompletedTask; }
    }
}

using CIS.Logging;
using CIS.Tests.DiscoveryFixture;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using static CIS.Tests.DiscoveryFixture.FlushStressSupport;

namespace CIS.Tests.UnitTests;

[TestClass]
public sealed class ConcurrencyQualificationTests
{
    [TestMethod]
    [DataRow(false)]
    [DataRow(true)]
    public async Task InvalidOnlyConcurrentCallsKeepZeroTargetsAndFreezeLossAtEachBoundary(bool dual)
    {
        var clock = new Clock(); using var console = new Writer(holdFirstWrite: false, holdFirstFlush: true); using var file = new Writer(holdFirstWrite: false, holdFirstFlush: true);
        CoreLogRuntime runtime = CoreLogRuntime.CreateQueued(ConsoleCompositionFixture.Metadata(),
            new LoggingOptions { ConsoleLevel = CoreLogLevel.Information, FileLevel = dual ? CoreLogLevel.Warning : CoreLogLevel.None, FilePath = dual ? "controlled" : null, QueueCapacity = 2 },
            console.WriteAsync, dual ? file.WriteAsync : null, clock, console.FlushAsync, dual ? file.FlushAsync : null);
        try
        {
            CoreLogger logger = runtime.CreateLogger("InvalidOnly");
            Task<LogFlushResult> original = runtime.FlushAsync(TimeSpan.FromSeconds(5), CancellationToken.None);
            await console.FirstFlush.Task.WaitAsync(Guard);
            if (dual) { await file.FirstFlush.Task.WaitAsync(Guard); }
            Assert.IsFalse(original.IsCompleted);
            var go = Signal(); int factories = 0;
            Task<LogWriteResult>[] callers = Enumerable.Range(0, 64).Select(index => Task.Run(async () =>
            {
                await go.Task;
                return index % 2 == 0 ? logger.Write(CoreLogLevel.Error, new() { EventName = "", Message = "invalid" })
                    : logger.WriteLazy(CoreLogLevel.Error, () => { Interlocked.Increment(ref factories); return null!; });
            })).ToArray();
            go.TrySetResult(); LogWriteResult[] outcomes = await Task.WhenAll(callers).WaitAsync(Guard);
            Assert.IsTrue(outcomes.All(r => r.Outcome == LogWriteOutcome.InvalidEvent && r.Outputs.Count == 0));
            Assert.AreEqual(32, factories); Assert.AreEqual(64L, runtime.GetDiagnostics().InvalidEventCount);
            Assert.IsTrue(runtime.GetDiagnostics().Outputs.All(o => o.Accepted == 0 && o.AdmissionAttempts == 0 && o.Pending == 0));
            Task<LogFlushResult> afterLoss = runtime.FlushAsync(TimeSpan.FromSeconds(5), CancellationToken.None);
            Assert.IsFalse(afterLoss.IsCompleted);
            Assert.AreEqual(1, runtime.QueuedOutputs!.Console!.RegisteredFlushCount);
            if (dual) { Assert.AreEqual(1, runtime.QueuedOutputs.File!.RegisteredFlushCount); }
            console.ReleaseAll(); file.ReleaseAll();
            LogFlushResult early = await original.WaitAsync(Guard), late = await afterLoss.WaitAsync(Guard);
            Assert.IsTrue(early.Succeeded && !early.LossObserved); Assert.AreEqual(0L, early.InvalidEventCount);
            Assert.IsTrue(late.Succeeded && late.LossObserved); Assert.AreEqual(64L, late.InvalidEventCount);
            Assert.AreEqual(dual ? 2 : 1, late.Outputs.Count);
            Assert.IsTrue(early.Outputs.Concat(late.Outputs).All(o => o.AcceptedSequenceBoundary == 0 && o.Written == 0 && o.Failed == 0 && o.Abandoned == 0 && o.Pending == 0));
            LogStopResult stop = await runtime.StopAsync(CancellationToken.None).WaitAsync(Guard);
            Assert.IsTrue(stop.Succeeded && stop.LossObserved); Assert.AreEqual(64L, stop.InvalidEventCount);
            Assert.IsTrue(stop.Outputs.All(o => o.AcceptedSequenceBoundary == 0));
            Assert.AreEqual(0, console.Writes); Assert.AreEqual(0, file.Writes); Assert.AreEqual(0L, console.Bytes.Length); Assert.AreEqual(0L, file.Bytes.Length);
            Assert.AreEqual(0L, early.InvalidEventCount); Assert.IsFalse(early.LossObserved);
        }
        finally { console.ReleaseAll(); file.ReleaseAll(); await runtime.DisposeAsync().AsTask().WaitAsync(Guard); }
    }

    [TestMethod]
    public async Task PublicPendingGaugeFallsRefillsAndSettlesWhileACapturedProducerLosesToStop()
    {
        var clock = new Clock(); using var writer = new Writer(holdSecondWrite: true);
        CoreLogRuntime runtime = CoreLogRuntime.CreateQueued(ConsoleCompositionFixture.Metadata(),
            new LoggingOptions { ConsoleLevel = CoreLogLevel.Information, FileLevel = CoreLogLevel.None, QueueCapacity = 2 }, writer.WriteAsync, null, clock, writer.FlushAsync);
        var captureEntered = Signal(); var releaseCapture = Signal(); Task<LogWriteResult>? captured = null;
        try
        {
            CoreLogger logger = runtime.CreateLogger("PendingGauge"); var pending = new List<long>();
            void Observe(long expected)
            {
                LogOutputDiagnostics output = runtime.GetDiagnostics().Outputs.Single();
                Assert.AreEqual(expected, output.Pending); Assert.AreEqual(output.Accepted, output.Written + output.Failed + output.Abandoned + output.Pending); pending.Add(output.Pending);
            }
            Accepted(logger.Write(CoreLogLevel.Information, Data("first"))); await writer.FirstWrite.Task.WaitAsync(Guard); Observe(1);
            Accepted(logger.Write(CoreLogLevel.Information, Data("second"))); Accepted(logger.Write(CoreLogLevel.Information, Data("third"))); Observe(3);
            LogOutputDiagnostics frozen = runtime.GetDiagnostics().Outputs.Single();
            Assert.AreEqual(LogWriteOutcome.Rejected, logger.Write(CoreLogLevel.Information, Data("full")).Outcome);
            using (var cancelled = new CancellationTokenSource())
            {
                cancelled.Cancel();
                try { await runtime.FlushAsync(TimeSpan.FromSeconds(5), cancelled.Token); Assert.Fail("Expected cancellation."); }
                catch (OperationCanceledException error) { Assert.AreEqual(cancelled.Token, error.CancellationToken); }
                Assert.AreEqual(1, runtime.QueuedOutputs!.Console!.RegisteredFlushCount);
                Assert.AreEqual(0, QueueGauge(runtime.QueuedOutputs.Console)["attached"]!.GetValue<int>()); Assert.AreEqual(0, clock.Created);
            }
            writer.ReleaseFirst.TrySetResult(); await writer.SecondWrite.Task.WaitAsync(Guard); Observe(2);
            Accepted(logger.Write(CoreLogLevel.Information, Data("refill"))); Observe(3);
            captured = Task.Run(() => logger.WriteLazy(CoreLogLevel.Information, () =>
            { captureEntered.TrySetResult(); Require(releaseCapture.Task.Wait(Guard)); return Data("late-capture"); }));
            await captureEntered.Task.WaitAsync(Guard);
            Task<LogStopResult> shared = runtime.StopAsync(CancellationToken.None); Assert.IsTrue(runtime.GetDiagnostics().AdmissionClosed);
            releaseCapture.TrySetResult(); Assert.AreEqual(LogWriteOutcome.Stopped, (await captured.WaitAsync(Guard)).Outcome);
            int stoppedFactories = 0;
            Assert.AreEqual(LogWriteOutcome.Stopped, logger.WriteLazy(CoreLogLevel.None, () => { stoppedFactories++; return Data("never"); }).Outcome); Assert.AreEqual(0, stoppedFactories);
            writer.ReleaseAll(); LogStopResult stop = await shared.WaitAsync(Guard); Observe(0);
            Assert.IsTrue(stop.Succeeded && stop.LossObserved); Assert.AreEqual(0L, stop.InvalidEventCount);
            Assert.AreEqual(4L, stop.Outputs.Single().Written); Assert.AreEqual(4L, stop.Outputs.Single().AcceptedSequenceBoundary);
            Assert.AreEqual(1L, stop.Outputs.Single().Rejections.QueueFull); Assert.AreEqual(0L, stop.Outputs.Single().Rejections.Unavailable);
            Assert.AreEqual(3L, frozen.Pending); Assert.AreEqual(0L, frozen.Written);
            CollectionAssert.AreEqual(new long[] { 1, 3, 2, 3, 0 }, pending);
            Assert.AreSame(shared, runtime.StopAsync(CancellationToken.None)); Assert.AreSame(stop, runtime.GetDiagnostics().LastStopResult);
            Assert.AreEqual(1, writer.Maximum); Assert.AreEqual(4, writer.Writes);
        }
        finally
        {
            releaseCapture.TrySetResult(); writer.ReleaseAll();
            if (captured is not null) { await captured.WaitAsync(Guard); }
            await runtime.DisposeAsync().AsTask().WaitAsync(Guard);
        }
    }
}

using System.Reflection;
