        JsonObject row = ConfigurationFixtureAdapter.Case(Read(), id);
        JsonObject input = row["inputs"]!.AsObject();
        string initial = ConfigurationFixtureAdapter.Text(input, "workingDirectoryAtInitialization") ?? SyntheticBase();
        int reads = 0;
