    [TestMethod]
    [DataRow("logs/app.jsonl", "logs/app.jsonl")]
    [DataRow("./logs/../log.jsonl", "log.jsonl")]
    [DataRow("../up.jsonl", "../up.jsonl")]
    [DataRow("logs/\u03a9-\U0001f642-e\u0301.jsonl", "logs/\u03a9-\U0001f642-e\u0301.jsonl")]
