            ? many.Select(issue => issue!["code"]!.GetValue<string>() + ":" + issue["key"]!.GetValue<string>()).ToArray()
            : row["expectedIssue"] is { } one ? [one["code"]!.GetValue<string>() + ":" + one["key"]!.GetValue<string>()] : [];
