using CIS.Configuration;

namespace CIS.Tests.UnitTests.Discovery;

internal sealed class EnvironmentVariableStub
{
    public Dictionary<string, string?> Values { get; } = new(StringComparer.Ordinal);
    public List<string> Reads { get; } = [];
    public string? FailingName { get; init; }
    public Exception? Failure { get; init; }

    public string? GetValue(string name)
    {
        Reads.Add(name);
        if (name == FailingName)
        {
            throw Failure ?? new IOException("Variable access unavailable");
        }

        return Values.GetValueOrDefault(name);
    }
}

namespace CIS.Tests.UnitTests.Discovery;

internal sealed class InitializationTimeProvider(DateTimeOffset utcNow) : TimeProvider
{
    public DateTimeOffset UtcNow { get; set; } = utcNow;
    public int Reads { get; private set; }
    public Exception? Failure { get; init; }

    public override DateTimeOffset GetUtcNow()
    {
        Reads++;
        if (Failure is not null)
        {
            throw Failure;
        }

        return UtcNow;
    }
}

