        }
        CapturedException root = ExceptionProjection.Capture(source.Root)!;
        ExceptionBoundaryFixture.Verify(id, ExceptionBoundaryFixture.Observe(id, root));
        foreach (ExceptionReadProbe probe in source.Probes)
        {
