        if (damage == "invalid-utf8") { File.WriteAllBytes(MetadataPath(path), [.. Encoding.UTF8.GetBytes(text[..^1] + ",\"future\":\""), 0xff, .. Encoding.UTF8.GetBytes("\"}")]); }
