    {
        using var root = new TemporaryDirectory(); string path = Path.Combine(root.Path, "active.log");
        using (var writer = Writer(path, format, 3)) { writer.Initialize(); for (int id = 1; id <= 5; id++) { await Write(writer, Record(format, id)); } }
