using System.Text.Json;
using CIS.TypeManagement;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace CIS.Tests.UnitTests;

[TestClass]
[DoNotParallelize]
public sealed class TypeManagerFreshAssemblyTests
{
    private const string ReferenceAttributeName = "System.Runtime.CompilerServices.ReferenceAssemblyAttribute";
    private string directory = null!;
    private string manifest = null!;
    private static Assembly Host => typeof(TypeManagerFreshAssemblyTests).Assembly;

    public TestContext TestContext { get; set; } = null!;

    [TestInitialize]
    public void Initialize()
    {
        directory = Path.GetFullPath(Path.Combine(TestContext.TestRunDirectory!, "cis-type-manager-fresh", Guid.NewGuid().ToString("N")));
        Directory.CreateDirectory(directory);
        File.Copy(Host.Location, Path.Combine(directory, "Host.dll"));
        manifest = Path.Combine(directory, "host.types.json");
    }

    // Default-context assemblies stay mapped until the test host exits.
    // Files accumulate under test output across runs; remove cis-type-manager-fresh
    // only after every test host using that output has exited.

    [TestMethod]
    public async Task NewPhysicalAssetIsPublishedAndThenReusedWithoutActivation()
    {
        var selected = Emit("Fresh", "Fresh.dll");
        AssertNotLoaded(selected.Name);
        WriteInventory(selected);
        var manager = await Create();
        var loaded = manager.Assemblies.Single(assembly => assembly.FullName == selected.Identity);
        Assert.IsFalse(loaded.IsDynamic);
        Assert.AreSame(AssemblyLoadContext.Default, AssemblyLoadContext.GetLoadContext(loaded));
        Assert.AreEqual(selected.Path, loaded.Location);
        var candidate = loaded.GetType("Fixtures.Candidate", throwOnError: true)!;
        Assert.Contains(candidate, manager.GetDefinedTypes(loaded));
        Assert.Contains(candidate, manager.GetImplementations<object>());
        CollectionAssert.AreEqual(new[] { selected.Identity }, manager.PreparationReport.LoadedAssemblyIdentities.ToArray());
        CollectionAssert.AreEqual(new[] { Host.FullName! }, manager.PreparationReport.ReusedAssemblyIdentities.ToArray());
        var repeated = await Create();
        Assert.AreSame(loaded, repeated.Assemblies.Single(assembly => assembly.FullName == selected.Identity));
        Assert.IsEmpty(repeated.PreparationReport.LoadedAssemblyIdentities);
        Assert.HasCount(2, repeated.PreparationReport.ReusedAssemblyIdentities);
    }

    [TestMethod]
    public async Task FileIdentityConflictRejectsTheWholeSelectionBeforeAnyNewLoad()
    {
        var first = Emit("AA_First", "First.dll");
        var last = Emit("ZZ_Last", "Last.dll");
        var expectedName = new AssemblyName(last.Identity) { Version = new Version(2, 0, 0, 0) };
        WriteInventory(first, last with { Identity = expectedName.FullName! });
        AssertNotLoaded(first.Name);
        AssertNotLoaded(last.Name);
        var failure = await Assert.ThrowsExactlyAsync<TypeManagerInitializationException>(Create);
        AssertIdentityFailure(failure, last.Path, expectedName.FullName!, last.Identity);
        AssertNotLoaded(first.Name);
        AssertNotLoaded(last.Name);
    }

    [TestMethod]
    public async Task ExistingCaseInsensitiveNameConflictIsDetectedBeforeAnyNewLoad()
    {
        var first = Emit("AA_First", "First.dll");
        string name = "ZZ_Case_" + Guid.NewGuid().ToString("N");
        var selected = Emit(name, "Selected.dll", exactName: true);
        var other = Emit(name.ToLowerInvariant(), "Other.dll", exactName: true);
        var existing = AssemblyLoadContext.Default.LoadFromAssemblyPath(other.Path);
        WriteInventory(first, selected);
        AssertNotLoaded(first.Name);
        var failure = await Assert.ThrowsExactlyAsync<TypeManagerInitializationException>(Create);
        AssertIdentityFailure(failure, selected.Path, selected.Identity, existing.FullName!);
        AssertNotLoaded(first.Name);
    }

    [TestMethod]
    public async Task ResolverSubstitutionMustMatchTheSelectedFullIdentity()
    {
        string name = "Resolver_" + Guid.NewGuid().ToString("N");
        var selected = Emit(name, "Selected.dll", exactName: true);
        var other = Emit(name, "Other.dll", exactName: true, version: 2);
        WriteInventory(selected);
        AssertNotLoaded(name);
        int calls = 0;
        Assembly? Resolve(AssemblyLoadContext context, AssemblyName requested)
        {
            if (requested.Name != name) { return null; }
            calls++;
            return context.LoadFromAssemblyPath(other.Path);
        }
        AssemblyLoadContext.Default.Resolving += Resolve;
        try
        {
            var failure = await Assert.ThrowsExactlyAsync<TypeManagerInitializationException>(Create);
            AssertIdentityFailure(failure, selected.Path, selected.Identity, other.Identity);
            Assert.AreEqual(1, calls);
        }
        finally { AssemblyLoadContext.Default.Resolving -= Resolve; }
    }

    [TestMethod]
    [DataRow("external")]
    [DataRow("defined")]
    public async Task ReferenceAttributeIsRejectedBeforeAnyNewLoad(string form)
    {
        var first = Emit("AA_First", "First.dll");
        var reference = Emit("ZZ_Reference", "Reference.dll", attribute: form);
        WriteInventory(first, reference);
        AssertNotLoaded(first.Name);
        AssertNotLoaded(reference.Name);
        var failure = await Assert.ThrowsExactlyAsync<TypeManagerInitializationException>(Create);
        Assert.AreEqual(TypeManagerFailureKind.AssemblyLoadFailure, failure.FailureKind);
        Assert.AreEqual(reference.Path, failure.AssetPath);
        Assert.AreEqual(reference.Identity, failure.AssemblyIdentity);
        Assert.AreEqual(manifest, failure.ManifestPath);
        Assert.IsInstanceOfType<BadImageFormatException>(failure.InnerException);
        AssertNotLoaded(first.Name);
        AssertNotLoaded(reference.Name);
    }

    [TestMethod]
    [DataRow("Other.Namespace.ReferenceAssemblyAttribute")]
    [DataRow("System.Runtime.CompilerServices.OtherAttribute")]
    public async Task SimilarAttributeNamesAreExecutableAndNeverInstantiated(string attribute)
    {
        var selected = Emit("Similar", "Similar.dll", attribute: attribute);
        WriteInventory(selected);
        AssertNotLoaded(selected.Name);
        var manager = await Create();
        var loaded = manager.Assemblies.Single(assembly => assembly.FullName == selected.Identity);
        Assert.Contains(loaded.GetType("Fixtures.Candidate", true)!, manager.Types);
        Assert.Contains(loaded.GetType(attribute, true)!, manager.Types);
    }

    private void AssertIdentityFailure(TypeManagerInitializationException failure, string path, string expectedSelectedIdentity, string expectedObservedIdentity)
    {
        Assert.AreEqual(TypeManagerFailureKind.AssemblyIdentityConflict, failure.FailureKind);
        Assert.AreEqual(manifest, failure.ManifestPath);
        Assert.AreEqual(path, failure.AssetPath);
        Assert.AreEqual(expectedSelectedIdentity, failure.AssemblyIdentity);
        Assert.AreEqual(expectedObservedIdentity, failure.ActualAssemblyIdentity);
        Assert.IsInstanceOfType<FileLoadException>(failure.InnerException);
    }

    private Task<ITypeManager> Create() => TypeManager.CreateAsync(new TypeManagerOptions(Host) { AssemblyManifestPath = manifest });

    private static void AssertNotLoaded(string name) => Assert.IsFalse(AssemblyLoadContext.Default.Assemblies.Any(
        assembly => string.Equals(assembly.GetName().Name, name, StringComparison.OrdinalIgnoreCase)));

    private void WriteInventory(params Selection[] selected) => File.WriteAllText(manifest, JsonSerializer.Serialize(new
    {
        schemaVersion = 1,
        hostAssembly = Host.FullName,
        assemblies = new[] { new { assemblyName = Host.FullName!, relativePath = "Host.dll" } }
            .Concat(selected.Select(item => new { assemblyName = item.Identity, relativePath = Path.GetFileName(item.Path) }))
    }));

    private Selection Emit(string prefix, string filename, bool exactName = false, int version = 1, string? attribute = null)
    {
        string name = exactName ? prefix : prefix + "_" + Guid.NewGuid().ToString("N");
        var identity = new AssemblyName(name) { Version = new Version(version, 0, 0, 0) };
        var builder = new PersistedAssemblyBuilder(identity, typeof(object).Assembly);
        var module = builder.DefineDynamicModule(name);
        var candidate = module.DefineType("Fixtures.Candidate", TypeAttributes.Public | TypeAttributes.Class);
        var constructor = candidate.DefineConstructor(MethodAttributes.Private, CallingConventions.Standard, Type.EmptyTypes);
        var body = constructor.GetILGenerator();
        body.Emit(OpCodes.Ldstr, "Candidate activation is forbidden during discovery.");
        body.Emit(OpCodes.Newobj, typeof(InvalidOperationException).GetConstructor([typeof(string)])!);
        body.Emit(OpCodes.Throw);
        candidate.CreateType();
        ConstructorBuilder? attributeConstructor = null;
        if (attribute == "external")
        {
            builder.SetCustomAttribute(new CustomAttributeBuilder(typeof(ReferenceAssemblyAttribute).GetConstructor(Type.EmptyTypes)!, []));
        }
        else if (attribute is not null)
        {
            string typeName = attribute == "defined" ? ReferenceAttributeName : attribute;
            var type = module.DefineType(typeName, TypeAttributes.Public | TypeAttributes.Class | TypeAttributes.Sealed, typeof(Attribute));
            var ctor = type.DefineConstructor(MethodAttributes.Public, CallingConventions.Standard, Type.EmptyTypes);
            var il = ctor.GetILGenerator();
            il.Emit(OpCodes.Ldstr, "Attribute activation is forbidden during discovery.");
            il.Emit(OpCodes.Newobj, typeof(InvalidOperationException).GetConstructor([typeof(string)])!);
            il.Emit(OpCodes.Throw);
            type.CreateType();
            attributeConstructor = ctor;
        }
        string path = Path.Combine(directory, filename);
        var metadata = builder.GenerateMetadata(out var methodBodies, out var fieldData);
        if (attributeConstructor is not null)
        {
            // Persisted member tokens are assigned by GenerateMetadata. Bind the
            // assembly attribute only after its local constructor has a real token.
            metadata.AddCustomAttribute(EntityHandle.AssemblyDefinition,
                MetadataTokens.MethodDefinitionHandle(attributeConstructor.MetadataToken),
                metadata.GetOrAddBlob(new byte[] { 1, 0, 0, 0 }));
        }
        var pe = new ManagedPEBuilder(PEHeaderBuilder.CreateLibraryHeader(),
            new MetadataRootBuilder(metadata), methodBodies, mappedFieldData: fieldData);
        var bytes = new BlobBuilder();
        pe.Serialize(bytes);
        using (var output = File.Create(path)) { bytes.WriteContentTo(output); }
        if (attribute is not null)
        {
            using var checkStream = File.OpenRead(path);
            using var checkExecutable = new PEReader(checkStream);
            var reader = checkExecutable.GetMetadataReader();
            var token = reader.GetCustomAttribute(reader.GetAssemblyDefinition().GetCustomAttributes().Single()).Constructor;
            Assert.AreEqual(attribute == "external" ? HandleKind.MemberReference : HandleKind.MethodDefinition, token.Kind);
            if (attribute != "external")
            {
                var declaringType = reader.GetMethodDefinition((MethodDefinitionHandle)token).GetDeclaringType();
                var definition = reader.GetTypeDefinition(declaringType);
                Assert.AreEqual(attribute == "defined" ? ReferenceAttributeName : attribute,
                    reader.GetString(definition.Namespace) + "." + reader.GetString(definition.Name));
            }
        }
        return new Selection(name, AssemblyName.GetAssemblyName(path).FullName!, path);
    }

    private sealed record Selection(string Name, string Identity, string Path);
}

using System.Reflection;
using System.Reflection.Emit;
using System.Runtime.Loader;
using System.Text.Json;
using CIS.TypeManagement;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace CIS.Tests.UnitTests;

[TestClass]
public sealed class TypeManagerInputTests
{
    private static Assembly Host => typeof(TypeManagerInputTests).Assembly;

    [TestMethod]
    public void NullArgumentsFailSynchronouslyBeforeReadingAnyInventory()
    {
        Assert.Throws<ArgumentNullException>(() => TypeManager.CreateAsync(null!));
        Assert.Throws<ArgumentNullException>(() => TypeManager.CreateAsync(new TypeManagerOptions(null!)));
        Assert.Throws<ArgumentNullException>(() => TypeManager.CreateAsync(new TypeManagerOptions(Host) { PrecomputedContracts = null! }));
        Assert.Throws<ArgumentNullException>(() => TypeManager.CreateAsync(new TypeManagerOptions(Host) { PrecomputedContracts = [null!] }));
        var extensionError = Assert.ThrowsExactly<ArgumentNullException>(() => TypeManagerExtensions.GetImplementations<object>(null!));
        Assert.AreEqual("manager", extensionError.ParamName);
    }

    [TestMethod]
    [DataRow("")]
    [DataRow(" ")]
    [DataRow("\t\r\n")]
    public void BlankAlternatePathIsAnArgumentError(string path)
    {
        Assert.Throws<ArgumentException>(() => TypeManager.CreateAsync(new TypeManagerOptions(Host) { AssemblyManifestPath = path }));
    }

    [TestMethod]
    public void InvalidPathTextNamesThePublicOptionsParameter()
    {
        var error = Assert.Throws<ArgumentException>(() => TypeManager.CreateAsync(new TypeManagerOptions(Host) { AssemblyManifestPath = "bad\0path" }));
        Assert.AreEqual("options", error.ParamName);
        Assert.IsInstanceOfType<ArgumentException>(error.InnerException);
    }

    [TestMethod]
    public void InputsAreOwnedAndDefaultPathUsesTheSuppliedHostName()
    {
        var list = new List<Type> { typeof(IDisposable), typeof(IDisposable) };
        var input = PreparationInputs.Capture(new TypeManagerOptions(Host) { PrecomputedContracts = list });
        list.Clear();
        list.Add(typeof(int));
        CollectionAssert.AreEqual(new[] { typeof(IDisposable) }, input.Contracts);
        Assert.AreEqual(Path.Combine(AppContext.BaseDirectory, Host.GetName().Name + ".types.json"), input.ManifestPath);
    }

    [TestMethod]
    [DataRow("value")]
    [DataRow("nullable")]
    [DataRow("open-generic")]
    [DataRow("type-parameter")]
    [DataRow("array")]
    [DataRow("pointer")]
    [DataRow("byref")]
    [DataRow("function-pointer")]
    [DataRow("delegated")]
    public async Task UnsupportedTypeShapesAreRejectedBeforePreparationAndByPublishedQueries(string shape)
    {
        Type type = shape switch
        {
            "value" => typeof(int),
            "nullable" => typeof(int?),
            "open-generic" => typeof(List<>),
            "type-parameter" => typeof(List<>).GetGenericArguments()[0],
            "array" => typeof(int[]),
            "pointer" => typeof(int).MakePointerType(),
            "byref" => typeof(int).MakeByRefType(),
            "function-pointer" => typeof(FunctionPointerHolder).GetField(nameof(FunctionPointerHolder.Pointer))!.FieldType,
            "delegated" => new TypeDelegator(typeof(IDisposable)),
            _ => throw new ArgumentException(shape, nameof(shape))
        };
        Assert.Throws<ArgumentException>(() => PreparationInputs.ValidateContract(type));
        Assert.Throws<ArgumentException>(() => TypeManager.CreateAsync(new TypeManagerOptions(Host) { PrecomputedContracts = [type] }));
        var manager = await CreateManager();
        var queryError = Assert.ThrowsExactly<ArgumentException>(() => manager.GetImplementations(type));
        Assert.AreEqual("contractType", queryError.ParamName);
        Assert.IsNotNull(manager.GetImplementations<object>());
    }

    [TestMethod]
    public async Task ForeignContextIsRejectedInsideClosedGenericContractsAndForTheHost()
    {
        var context = new AssemblyLoadContext("type-manager-input-test", isCollectible: true);
        try
        {
            var foreignAssembly = context.LoadFromAssemblyPath(Host.Location);
            var foreignType = foreignAssembly.GetType(typeof(TypeManagerInputTests).FullName!)!;
            Assert.Throws<ArgumentException>(() => PreparationInputs.ValidateContract(foreignType));
            Assert.Throws<ArgumentException>(() => PreparationInputs.ValidateContract(typeof(IEnumerable<>).MakeGenericType(foreignType)));
            Assert.Throws<ArgumentException>(() => TypeManager.CreateAsync(new TypeManagerOptions(foreignAssembly)));
            var manager = await CreateManager();
            Assert.ThrowsExactly<ArgumentException>(() => manager.GetImplementations(foreignType));
            Assert.ThrowsExactly<ArgumentException>(() => manager.GetImplementations(typeof(IEnumerable<>).MakeGenericType(foreignType)));
        }
        finally { context.Unload(); }
    }

    [TestMethod]
    public async Task DynamicTypesAndTheirHostAssemblyAreRejected()
    {
        var assembly = AssemblyBuilder.DefineDynamicAssembly(new AssemblyName("DynamicInput_" + Guid.NewGuid().ToString("N")), AssemblyBuilderAccess.Run);
        var dynamicType = assembly.DefineDynamicModule("Main").DefineType("DynamicType", TypeAttributes.Public).CreateType()!;
        Assert.Throws<ArgumentException>(() => PreparationInputs.ValidateContract(dynamicType));
        Assert.Throws<ArgumentException>(() => TypeManager.CreateAsync(new TypeManagerOptions(assembly)));
        var manager = await CreateManager();
        Assert.ThrowsExactly<ArgumentException>(() => manager.GetImplementations(dynamicType));
    }

    [TestMethod]
    public void ClosedContractsWithValueOrArrayArgumentsRemainSupported()
    {
        PreparationInputs.ValidateContract(typeof(IEnumerable<int>));
        PreparationInputs.ValidateContract(typeof(IEnumerable<string[]>));
        PreparationInputs.ValidateContract(typeof(Dictionary<string, List<int>>));
    }

    private static async Task<ITypeManager> CreateManager()
    {
        string directory = Path.Combine(Path.GetTempPath(), "cis-type-manager-query-arguments", Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(directory);
        try
        {
            File.Copy(Host.Location, Path.Combine(directory, "Host.dll"));
            string manifest = Path.Combine(directory, "host.types.json");
            await File.WriteAllTextAsync(manifest, JsonSerializer.Serialize(new
            {
                schemaVersion = 1,
                hostAssembly = Host.FullName,
                assemblies = new[] { new { assemblyName = Host.FullName, relativePath = "Host.dll" } }
            }));
            return await TypeManager.CreateAsync(new TypeManagerOptions(Host) { AssemblyManifestPath = manifest });
        }
        finally { Directory.Delete(directory, recursive: true); }
    }

    [TestMethod]
    public async Task AlreadyCanceledInputReturnsACanceledTask()
    {
        using var cancellation = new CancellationTokenSource();
        cancellation.Cancel();
        var preparation = TypeManager.CreateAsync(new TypeManagerOptions(Host), cancellation.Token);
        await Assert.ThrowsAsync<OperationCanceledException>(() => preparation);
        Assert.IsTrue(preparation.IsCanceled);
    }

    [TestMethod]
    public void RelativeManifestPathsUseTheApplicationDirectoryAndOptionErrorsNameOptions()
    {
        var input = PreparationInputs.Capture(new TypeManagerOptions(Host) { AssemblyManifestPath = "relative.types.json" });
        Assert.AreEqual(Path.Combine(AppContext.BaseDirectory, "relative.types.json"), input.ManifestPath);
        var invalid = Assert.Throws<ArgumentException>(() => TypeManager.CreateAsync(new TypeManagerOptions(Host) { PrecomputedContracts = [typeof(int)] }));
        Assert.AreEqual("options", invalid.ParamName);
    }

    private unsafe sealed class FunctionPointerHolder
    {
        public delegate*<void> Pointer = null;
    }
}

using System.Reflection;
using System.Text.Json.Nodes;
using CIS.TypeManagement;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace CIS.Tests.UnitTests;

[TestClass]
public sealed class TypeManagerManifestTests
{
    private string directory = null!;
    private string manifestPath = null!;
    private static Assembly Host => typeof(TypeManagerManifestTests).Assembly;

    [TestInitialize]
    public void Initialize()
    {
        directory = Path.Combine(Path.GetTempPath(), "cis-type-manager-tests", Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(directory);
        File.Copy(Host.Location, Path.Combine(directory, "Host.dll"));
        manifestPath = Path.Combine(directory, "host.types.json");
    }

    [TestCleanup]
    public void Cleanup() => Directory.Delete(directory, recursive: true);

    [TestMethod]
    public async Task ValidInventoryIgnoresAdditiveFieldsAndDeduplicatesIdenticalEntries()
    {
        var json = Valid();
        json["future"] = new JsonObject { ["nested"] = new JsonArray(1, 2) };
        json["assemblies"]!.AsArray().Add(json["assemblies"]![0]!.DeepClone());
        await Save(json);
        var inventory = await AssemblyInventory.ReadAsync(manifestPath, Host, default);
        Assert.HasCount(1, inventory.Assemblies);
        Assert.AreEqual(Host.FullName, inventory.Assemblies[0].Identity);
        Assert.Throws<NotSupportedException>(() => ((IList<SelectedAssembly>)inventory.Assemblies).Clear());
    }

    [TestMethod]
    [DataRow("schema-missing")]
    [DataRow("schema-string")]
    [DataRow("schema-null")]
    [DataRow("schema-fraction")]
    [DataRow("schema-new")]
    [DataRow("host-missing")]
    [DataRow("host-mismatch")]
    [DataRow("host-not-selected")]
    [DataRow("assemblies-missing")]
    [DataRow("assemblies-object")]
    [DataRow("assemblies-empty")]
    [DataRow("entry-scalar")]
    [DataRow("identity-simple")]
    [DataRow("identity-blank")]
    [DataRow("path-null")]
    [DataRow("path-empty")]
    [DataRow("path-missing-file")]
    [DataRow("path-rooted")]
    [DataRow("path-parent")]
    [DataRow("path-backslash")]
    [DataRow("path-uri")]
    [DataRow("path-dot")]
    [DataRow("path-empty-segment")]
    [DataRow("identity-conflict")]
    [DataRow("version-conflict")]
    [DataRow("path-conflict")]
    public async Task InvalidInputsFailWithManifestAndOriginalCause(string mode)
    {
        var json = Valid();
        var entry = json["assemblies"]![0]!.AsObject();
        switch (mode)
        {
            case "schema-missing": json.Remove("schemaVersion"); break;
            case "schema-string": json["schemaVersion"] = "1"; break;
            case "schema-null": json["schemaVersion"] = null; break;
            case "schema-fraction": json["schemaVersion"] = 1.5; break;
            case "schema-new": json["schemaVersion"] = 2; break;
            case "host-missing": json.Remove("hostAssembly"); break;
            case "host-mismatch": json["hostAssembly"] = typeof(object).Assembly.FullName; break;
            case "host-not-selected": entry["assemblyName"] = "Other, Version=1.0.0.0, Culture=neutral, PublicKeyToken=null"; break;
            case "assemblies-missing": json.Remove("assemblies"); break;
            case "assemblies-object": json["assemblies"] = new JsonObject(); break;
            case "assemblies-empty": json["assemblies"] = new JsonArray(); break;
            case "entry-scalar": json["assemblies"]![0] = 7; break;
            case "identity-simple": entry["assemblyName"] = Host.GetName().Name; break;
            case "identity-blank": entry["assemblyName"] = " "; break;
            case "path-null": entry["relativePath"] = null; break;
            case "path-empty": entry["relativePath"] = ""; break;
            case "path-missing-file": entry["relativePath"] = "missing.dll"; break;
            case "path-rooted": entry["relativePath"] = "/Host.dll"; break;
            case "path-parent": entry["relativePath"] = "../Host.dll"; break;
            case "path-backslash": entry["relativePath"] = "folder\\Host.dll"; break;
            case "path-uri": entry["relativePath"] = "file:///Host.dll"; break;
            case "path-dot": entry["relativePath"] = "./Host.dll"; break;
            case "path-empty-segment": entry["relativePath"] = "folder//Host.dll"; break;
            case "identity-conflict":
                File.Copy(Host.Location, Path.Combine(directory, "Other.dll"));
                json["assemblies"]!.AsArray().Add(new JsonObject { ["assemblyName"] = Host.FullName, ["relativePath"] = "Other.dll" });
                break;
            case "version-conflict":
                var changedVersion = Host.GetName();
                changedVersion.Version = new Version(9, 0, 0, 0);
                File.Copy(Host.Location, Path.Combine(directory, "Version9.dll"));
                json["assemblies"]!.AsArray().Add(new JsonObject { ["assemblyName"] = changedVersion.FullName, ["relativePath"] = "Version9.dll" });
                break;
            case "path-conflict":
                json["assemblies"]!.AsArray().Add(new JsonObject { ["assemblyName"] = "Other, Version=1.0.0.0, Culture=neutral, PublicKeyToken=null", ["relativePath"] = "Host.dll" });
                break;
            default: Assert.Fail(mode); break;
        }
        await Save(json);
        var error = await Assert.ThrowsAsync<TypeManagerInitializationException>(() => AssemblyInventory.ReadAsync(manifestPath, Host, default));
        Assert.AreEqual(TypeManagerFailureKind.InvalidInventory, error.FailureKind);
        Assert.AreEqual(manifestPath, error.ManifestPath);
        Assert.IsNotNull(error.InnerException);
        if (mode.StartsWith("path-", StringComparison.Ordinal) && mode is not "path-null" and not "path-empty")
        {
            Assert.IsFalse(string.IsNullOrWhiteSpace(error.AssetPath));
            Assert.IsFalse(string.IsNullOrWhiteSpace(error.AssemblyIdentity));
        }
    }

    [TestMethod]
    [DataRow("{")]
    [DataRow("[]")]
    public async Task MalformedOrDuplicateJsonIsNeverAccepted(string json)
    {
        await File.WriteAllTextAsync(manifestPath, json);
        var error = await Assert.ThrowsAsync<TypeManagerInitializationException>(() => AssemblyInventory.ReadAsync(manifestPath, Host, default));
        Assert.AreEqual(TypeManagerFailureKind.InvalidInventory, error.FailureKind);
    }

    [TestMethod]
    [DataRow("root")]
    [DataRow("entry")]
    [DataRow("unknown")]
    [DataRow("nested-array")]
    public async Task DuplicatePropertiesFailEvenWhenAllRequiredFieldsAreOtherwiseValid(string scope)
    {
        string json = Valid().ToJsonString();
        json = scope switch
        {
            "root" => json.Insert(1, "\"schemaVersion\":1,"),
            "entry" => json.Replace("\"relativePath\":\"Host.dll\"", "\"relativePath\":\"Host.dll\",\"relativePath\":\"Host.dll\"", StringComparison.Ordinal),
            "unknown" => json.Insert(1, "\"future\":{\"a\":1,\"a\":2},"),
            "nested-array" => json.Insert(1, "\"future\":[{\"a\":1,\"a\":2}],"),
            _ => throw new ArgumentException(scope)
        };
        await File.WriteAllTextAsync(manifestPath, json);
        var error = await Assert.ThrowsAsync<TypeManagerInitializationException>(() => AssemblyInventory.ReadAsync(manifestPath, Host, default));
        Assert.IsInstanceOfType<FormatException>(error.InnerException);
        StringAssert.Contains(error.InnerException.Message, "Duplicate JSON property");
    }

    [TestMethod]
    public async Task InvalidUtf8CannotBeReplacedWithAValidJsonString()
    {
        byte[] prefix = System.Text.Encoding.UTF8.GetBytes("{\"unknown\":\"");
        byte[] suffix = System.Text.Encoding.UTF8.GetBytes("\"," + Valid().ToJsonString()[1..]);
        await File.WriteAllBytesAsync(manifestPath, [.. prefix, 0xff, .. suffix]);
        var error = await Assert.ThrowsAsync<TypeManagerInitializationException>(() => AssemblyInventory.ReadAsync(manifestPath, Host, default));
        Assert.AreEqual(TypeManagerFailureKind.InvalidInventory, error.FailureKind);
    }

    [TestMethod]
    public async Task MissingManifestRetainsFileFailureAndCancellationIsNotWrapped()
    {
        var missing = await Assert.ThrowsAsync<TypeManagerInitializationException>(() => AssemblyInventory.ReadAsync(manifestPath, Host, default));
        Assert.IsInstanceOfType<FileNotFoundException>(missing.InnerException);
        using var cancellation = new CancellationTokenSource();
        cancellation.Cancel();
        await Assert.ThrowsAsync<OperationCanceledException>(() => AssemblyInventory.ReadAsync(manifestPath, Host, cancellation.Token));
    }

    [TestMethod]
    public async Task Utf8BomIsAcceptedAndHostMismatchHasBothIdentitiesInVisibleDiagnostics()
    {
        await File.WriteAllBytesAsync(manifestPath, [0xef, 0xbb, 0xbf, .. System.Text.Encoding.UTF8.GetBytes(Valid().ToJsonString())]);
        Assert.HasCount(1, (await AssemblyInventory.ReadAsync(manifestPath, Host, default)).Assemblies);
        var json = Valid();
        json["hostAssembly"] = typeof(object).Assembly.FullName;
        await Save(json);
        var error = await Assert.ThrowsAsync<TypeManagerInitializationException>(() => AssemblyInventory.ReadAsync(manifestPath, Host, default));
        Assert.AreEqual(typeof(object).Assembly.FullName, error.AssemblyIdentity);
        Assert.AreEqual(Host.FullName, error.ActualAssemblyIdentity);
        StringAssert.Contains(error.ToString(), manifestPath);
        StringAssert.Contains(error.ToString(), Host.FullName!);
        StringAssert.Contains(error.ToString(), typeof(object).Assembly.FullName!);
    }

    [TestMethod]
    public async Task PlatformPathRulesRejectWindowsAliasesAndRetainLinuxFilenames()
    {
        foreach (var invalid in new[] { "Host.dll.", "Host.dll " })
        {
            var json = Valid();
            json["assemblies"]![0]!["relativePath"] = invalid;
            await Save(json);
            if (OperatingSystem.IsWindows())
            {
                var error = await Assert.ThrowsAsync<TypeManagerInitializationException>(() => AssemblyInventory.ReadAsync(manifestPath, Host, default));
                Assert.AreEqual(TypeManagerFailureKind.InvalidInventory, error.FailureKind);
                StringAssert.Contains(error.Message, invalid);
            }
            else
            {
                File.Copy(Host.Location, Path.Combine(directory, invalid), overwrite: true);
                Assert.HasCount(1, (await AssemblyInventory.ReadAsync(manifestPath, Host, default)).Assemblies);
            }
        }
    }

    [TestMethod]
    public async Task PathCaseDuplicatesUseThePlatformComparisonRule()
    {
        File.Copy(Host.Location, Path.Combine(directory, "HOST.dll"), overwrite: true);
        var json = Valid();
        json["assemblies"]!.AsArray().Add(new JsonObject { ["assemblyName"] = Host.FullName, ["relativePath"] = "HOST.dll" });
        await Save(json);
        if (OperatingSystem.IsWindows())
        {
            Assert.HasCount(1, (await AssemblyInventory.ReadAsync(manifestPath, Host, default)).Assemblies);
        }
        else
        {
            var error = await Assert.ThrowsAsync<TypeManagerInitializationException>(() => AssemblyInventory.ReadAsync(manifestPath, Host, default));
            Assert.AreEqual(TypeManagerFailureKind.InvalidInventory, error.FailureKind);
        }
    }

    private Task Save(JsonObject json) => File.WriteAllTextAsync(manifestPath, json.ToJsonString());
    private static JsonObject Valid() => new()
    {
        ["schemaVersion"] = 1,
        ["hostAssembly"] = Host.FullName,
        ["assemblies"] = new JsonArray(new JsonObject { ["assemblyName"] = Host.FullName, ["relativePath"] = "Host.dll" })
    };
}

using System.Globalization;
using System.Reflection;
using System.Text.Json;
using CIS.TypeManagement;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace CIS.Tests.UnitTests;

[TestClass]
[DoNotParallelize]
public sealed class TypeManagerOrderingTests
{
    [TestMethod]
    [DataRow("en-US")]
    [DataRow("tr-TR")]
    [DataRow("sv-SE")]
    public async Task CultureAndValidInventoryOrderCannotChangePreparedOrLazyResults(string culture)
    {
        CultureInfo previous = CultureInfo.CurrentCulture;
        CultureInfo previousUi = CultureInfo.CurrentUICulture;
        string directory = Path.Combine(Path.GetTempPath(), "cis-type-manager-ordering", Guid.NewGuid().ToString("N"));
        Assembly host = typeof(TypeManagerOrderingTests).Assembly;
        Assembly core = typeof(TypeManager).Assembly;
        Assembly abstractions = typeof(Microsoft.Extensions.Logging.ILogger).Assembly;
        Assembly[] selected = [host, abstractions, core];
        string manifest = Path.Combine(directory, "host.types.json");
        try
        {
            Directory.CreateDirectory(directory);
            foreach (var assembly in selected) { File.Copy(assembly.Location, Path.Combine(directory, assembly.GetName().Name + ".dll")); }
            CultureInfo.CurrentCulture = CultureInfo.InvariantCulture;
            CultureInfo.CurrentUICulture = CultureInfo.InvariantCulture;
            WriteManifest(selected);
            var baseline = await Create(precompute: false);
            var baselineTypes = baseline.Types.ToArray();
            var baselineAssemblies = baseline.Assemblies.ToArray();
            CollectionAssert.AreEqual(new[] { core, host, abstractions }, baselineAssemblies);
            var baselineObjects = baseline.GetImplementations<object>().ToArray();

            CultureInfo.CurrentCulture = CultureInfo.GetCultureInfo(culture);
            CultureInfo.CurrentUICulture = CultureInfo.CurrentCulture;
            // These fixture names deliberately distinguish linguistic and ordinal
            // ordering. The expected query order is specified independently.
            Assert.IsLessThan(0, StringComparer.CurrentCulture.Compare(nameof(ÉclairCandidate), nameof(ZebraCandidate)));
            Assert.AreEqual('\u00C9', nameof(ÉclairCandidate)[0]);
            Type[] expected = [typeof(ZebraCandidate), typeof(ÉclairCandidate)];
            foreach (bool reverse in new[] { false, true })
            {
                WriteManifest(reverse ? selected.Reverse().ToArray() : selected);
                foreach (bool precompute in new[] { false, true })
                {
                    var manager = await Create(precompute);
                    CollectionAssert.AreEqual(baselineAssemblies, manager.Assemblies.ToArray());
                    CollectionAssert.AreEqual(baselineTypes, manager.Types.ToArray());
                    AssertOrdinalFixtureOrder(manager.Types);
                    AssertOrdinalFixtureOrder(manager.GetDefinedTypes(host));
                    CollectionAssert.AreEqual(baselineObjects, manager.GetImplementations<object>().ToArray());
                    var candidates = manager.GetImplementations<ICultureMarker>();
                    CollectionAssert.AreEqual(expected, candidates.ToArray());
                    Assert.AreSame(candidates, manager.GetImplementations(typeof(ICultureMarker)));
                    Assert.AreEqual(precompute ? 2 : 0, manager.PreparationReport.PreparedContractCount);
                    foreach (var assembly in selected)
                    {
                        CollectionAssert.AreEqual(baseline.GetDefinedTypes(assembly).ToArray(), manager.GetDefinedTypes(assembly).ToArray());
                    }
                    foreach (var type in expected)
                    {
                        Assert.IsTrue(manager.TryGetType(type.AssemblyQualifiedName!, out var found));
                        Assert.AreSame(type, found);
                    }
                    await Task.WhenAll(Enumerable.Range(0, 16).Select(_ => Task.Run(() =>
                    {
                        Assert.AreSame(candidates, manager.GetImplementations<ICultureMarker>());
                        CollectionAssert.AreEqual(baselineObjects, manager.GetImplementations<object>().ToArray());
                    })));
                }
            }
        }
        finally
        {
            CultureInfo.CurrentCulture = previous;
            CultureInfo.CurrentUICulture = previousUi;
            if (Directory.Exists(directory)) { Directory.Delete(directory, recursive: true); }
        }

        void WriteManifest(IEnumerable<Assembly> assemblies) => File.WriteAllText(manifest, JsonSerializer.Serialize(new
        {
            schemaVersion = 1,
            hostAssembly = host.FullName,
            assemblies = assemblies.Select(assembly => new
            {
                assemblyName = assembly.FullName,
                relativePath = assembly.GetName().Name + ".dll"
            }).ToArray()
        }));

        Task<ITypeManager> Create(bool precompute) => TypeManager.CreateAsync(new TypeManagerOptions(host)
        {
            AssemblyManifestPath = manifest,
            PrecomputedContracts = precompute ? [typeof(ICultureMarker), typeof(object)] : []
        });
    }

    private static void AssertOrdinalFixtureOrder(IReadOnlyList<Type> types)
    {
        var values = types.ToArray();
        int zebraIndex = Array.IndexOf(values, typeof(ZebraCandidate));
        int accentedIndex = Array.IndexOf(values, typeof(ÉclairCandidate));
        Assert.IsTrue(zebraIndex >= 0 && accentedIndex > zebraIndex,
            "Ordinal ordering must place ZebraCandidate before ÉclairCandidate.");
    }

    private interface ICultureMarker { }
    private sealed class ZebraCandidate : ICultureMarker { }
    private sealed class ÉclairCandidate : ICultureMarker { }
}

