namespace CIS.Tests.DiscoveryFixture;

// Shared observations for the native provider readers, never a shipping dependency.
internal static class ProviderReportChecks
{
    internal static void Require(bool value, string reason)
    {
        if (!value) { throw new InvalidDataException(reason); }
    }
    internal static bool Integer(JsonNode? value, long expected) =>
        value is JsonValue scalar && (scalar.TryGetValue<long>(out long actual) && actual == expected || scalar.TryGetValue<int>(out int small) && small == expected) &&
        value.ToJsonString() == expected.ToString(CultureInfo.InvariantCulture);
    internal static bool Same(JsonNode? actual, JsonNode? expected)
    {
        if (actual is null || expected is null) { return actual is null && expected is null; }
        if (actual.GetValueKind() != expected.GetValueKind()) { return false; }
        if (expected is JsonObject obj)
        {
            return actual is JsonObject value && value.Count == obj.Count &&
                obj.All(pair => value.ContainsKey(pair.Key) && Same(value[pair.Key], pair.Value));
        }
        if (expected is JsonArray array)
        {
            return actual is JsonArray value && value.Count == array.Count &&
                array.Select((item, index) => Same(value[index], item)).All(match => match);
        }
        if (expected.GetValueKind() == JsonValueKind.Number)
        {
            return (actual.ToJsonString().IndexOfAny(['.', 'e', 'E']) < 0) ==
                (expected.ToJsonString().IndexOfAny(['.', 'e', 'E']) < 0) && JsonNode.DeepEquals(actual, expected);
        }
        return JsonNode.DeepEquals(actual, expected);
    }
    internal static bool Same(JsonNode? actual, string expected) => Same(actual, JsonNode.Parse(expected));
    internal static void Header(string mode, string[] modes, JsonObject report, int? expectedPid)
    {
        Require(modes.Contains(mode, StringComparer.Ordinal) && (string?)report["mode"] == mode, "mode");
        Require((string?)report["runtime"] == ".NET 10.0.12", "actual runtime");
        Require(report["pid"] is JsonValue scalar && scalar.TryGetValue<int>(out int pid) && pid > 0 &&
            Integer(scalar, pid) && (expectedPid is null || pid == expectedPid), "actual child PID");
    }
    internal static JsonObject[] Rows(byte[] data, int count, string framingReason = "JSONL framing", string countReason = "bounded records")
    {
        Require(count == 0 ? data.Length == 0 : data.Length > 0 && data[^1] == 10 &&
            !data.AsSpan().StartsWith(new byte[] { 239, 187, 191 }) && !data.Contains((byte)13), framingReason);
        string[] lines = count == 0 ? [] : new UTF8Encoding(false, true).GetString(data)[..^1].Split('\n');
        Require(lines.All(line => line.Length > 0 && Encoding.UTF8.GetByteCount(line) + 1 <= 16384), "bounded records");
        Require(lines.Length == count, countReason);
        return lines.Select(line => JsonNode.Parse(line)!.AsObject()).ToArray();
    }
    internal static JsonObject[] Rows(JsonObject report, int count) =>
        Rows(Convert.FromBase64String(report["bytes"]!.GetValue<string>()), count);
    internal static void Identity(JsonObject row, JsonObject report, bool physical, string reason = "automatic core facts")
    {
        Require(Integer(row["schema_version"], 1) &&
            (string?)row["service"] == (physical ? "CIS.Core.DiscoveryFixture" : "Console.App"), reason);
        if (physical)
        {
            Require(Same(row["resource"]?["process_id"], report["pid"]) && Integer(row["resource"]?["process_id"], report["pid"]!.GetValue<int>()) &&
                (string?)row["resource"]?["runtime_description"] == ".NET 10.0.12" &&
                Same(row["resource"]?["os_family"], report["os"]), reason);
        }
    }
    internal static void Shape(JsonObject result)
    {
        Require(result.Select(pair => pair.Key).ToHashSet(StringComparer.Ordinal)
            .SetEquals(["completion", "succeeded", "loss", "captured", "observed", "outputs"]), "result shape");
    }
    internal static void Delivery(JsonNode output, int count, string reason)
    {
        string n = count.ToString(CultureInfo.InvariantCulture);
        Require((string?)output["boundary"] == n && (string?)output["written"] == n &&
            (string?)output["failed"] == "0" && (string?)output["abandoned"] == "0" &&
            (string?)output["pending"] == "0" && (string?)output["flush"] == "Succeeded", reason);
    }
    internal static void Stop(JsonObject report, int count, bool physical, bool loss,
        string summaryReason = "stop summary", string deliveryReason = "core delivery")
    {
        JsonObject result = report["result"]!.AsObject(); Shape(result);
        Require((string?)result["completion"] == "Completed" && Same(result["succeeded"], "true") &&
            Same(result["loss"], JsonValue.Create(loss)), summaryReason);
        JsonArray outputs = result["outputs"]!.AsArray();
        Require(outputs.Count == 1 && (string?)outputs[0]!["name"] == (physical ? "file" : "console"), "output selection");
        Delivery(outputs[0]!, count, deliveryReason);
    }
    internal static void Activity(JsonObject report, string trace = "trace", string span = "span")
    {
        string? value = (string?)report[span];
        Require((string?)report[trace] == new string('1', 32) && value is { Length: 16 } &&
            value.All(c => c is >= '0' and <= '9' or >= 'a' and <= 'f') && value.Any(c => c != '0'), "actual Activity");
    }
    internal static JsonObject Fields(int count, bool eventId = true, string? common = null)
    {
        var fields = new JsonObject();
        if (eventId) { fields["event_id"] = 17; }
        if (common is not null) { fields["common"] = common; }
        for (int i = 0; i < count; i++) { fields["k" + i.ToString("D4", CultureInfo.InvariantCulture)] = i; }
        return fields;
    }
}

using System.Diagnostics;
using System.Globalization;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Xml.Linq;
using CIS.TestSupport;

namespace CIS.Verification;

// A selected native run, not a replacement for a Developer or Release checkpoint.
internal static class FocusedTests
{
    internal sealed record Selection(string Root, string Project, string Configuration, string? Filter, int TimeoutSeconds);
    internal sealed record NativeCase(string Id, string ExecutionId, string Name, string Method, string Source, string Outcome);

    internal static Selection Parse(string[] arguments)
    {
        if (arguments.Length < 3 || arguments.Length % 2 != 1)
        { throw new ArgumentException("Usage: focused-test <language-root> --project UnitTests [--class Name | --category Name | --filter VSTestExpression] [--configuration Debug|Release] [--timeout-seconds 300]"); }
        var options = new Dictionary<string, string>(StringComparer.Ordinal);
        string[] known = ["--project", "--class", "--category", "--filter", "--configuration", "--timeout-seconds"];
        for (int index = 1; index < arguments.Length; index += 2)
        {
            if (!known.Contains(arguments[index], StringComparer.Ordinal) || string.IsNullOrWhiteSpace(arguments[index + 1]) || !options.TryAdd(arguments[index], arguments[index + 1]))
            { throw new ArgumentException("Unknown, empty or repeated focused-test option: " + arguments[index]); }
        }
        if (!options.TryGetValue("--project", out string? project)) { throw new ArgumentException("--project is required."); }
        string root = Path.GetFullPath(arguments[0]);
        JsonObject policy = JsonNode.Parse(File.ReadAllText(Path.Combine(root, "eng/project-boundaries.json")))!.AsObject();
        string[] registered = policy["projects"]!.AsArray().Where(item => item!["role"]!.GetValue<string>() == "test").Select(item => item!["path"]!.GetValue<string>()).ToArray();
        string? selected = registered.SingleOrDefault(path => project == path || project == Path.GetFileNameWithoutExtension(path) || "CIS.Core." + project == Path.GetFileNameWithoutExtension(path));
        if (selected is null) { throw new ArgumentException("Select a registered native test project, for example UnitTests or IntegrationTests."); }
        string configuration = options.GetValueOrDefault("--configuration", "Debug");
        if (configuration is not ("Debug" or "Release")) { throw new ArgumentException("Configuration must be Debug or Release."); }
        if (!int.TryParse(options.GetValueOrDefault("--timeout-seconds", "300"), NumberStyles.None, CultureInfo.InvariantCulture, out int timeout) || timeout is < 1 or > 3600)
        { throw new ArgumentException("Timeout must be 1–3600 seconds per child process."); }
        if (new[] { "--class", "--category", "--filter" }.Count(options.ContainsKey) > 1)
        { throw new ArgumentException("Choose one selector; use --filter for combined VSTest expressions."); }
        string? filter = options.GetValueOrDefault("--filter");
        foreach (string key in new[] { "--class", "--category" })
        {
            if (!options.TryGetValue(key, out string? value)) { continue; }
            if (value.Any(character => !char.IsLetterOrDigit(character) && character is not ('_' or '.' or '+' or '-' or ' ')))
            { throw new ArgumentException("Use --filter for selectors containing VSTest operators or special characters."); }
            filter = key == "--class" ? "FullyQualifiedName~" + value + "." : "TestCategory=" + value;
        }
        return new(root, selected, configuration, filter, timeout);
    }

    internal static async Task<int> RunAsync(string[] arguments)
    {
        Selection selection;
        try { selection = Parse(arguments); }
        catch (Exception error) when (error is ArgumentException or IOException or JsonException)
        { Console.Error.WriteLine(error.Message); return 2; }

        string repository = Path.GetFullPath(Path.Combine(selection.Root, "../.."));
        string output = Path.Combine(repository, ".artifacts/csharp/focused", Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(output);
        Console.WriteLine("Focused native results: " + output);
        DateTimeOffset started = DateTimeOffset.UtcNow;
        var elapsed = Stopwatch.StartNew();
        double buildSeconds = 0, nativeSeconds = 0;
        NativeCase[] cases = [];
        string? failure = null;
        try
        {
            await RunChild("build", ["build", selection.Project, "-c", selection.Configuration, "-p:RestoreLockedMode=true"]);
            buildSeconds = elapsed.Elapsed.TotalSeconds;
            var testArguments = new List<string> { "test", selection.Project, "-c", selection.Configuration, "--no-build", "--no-restore", "--logger", "trx;LogFileName=selected.trx", "--results-directory", output };
            if (selection.Filter is not null) { testArguments.AddRange(["--filter", selection.Filter]); }
            DateTimeOffset testStarted = DateTimeOffset.UtcNow;
            await RunChild("test", testArguments);
            nativeSeconds = elapsed.Elapsed.TotalSeconds - buildSeconds;
            cases = ReadResults(Path.Combine(output, "selected.trx"), testStarted);
        }
        catch (Exception error) when (error is IOException or InvalidDataException or InvalidOperationException or ArgumentException or FormatException or TimeoutException or System.Xml.XmlException or System.ComponentModel.Win32Exception)
        { failure = error.Message; Console.Error.WriteLine(failure); }
        elapsed.Stop();
        File.WriteAllText(Path.Combine(output, "summary.json"), JsonSerializer.Serialize(new
        {
            scope = "focused-native-tests",
            passed = failure is null,
            failure,
            started,
            selection.Project,
            selection.Configuration,
            selection.Filter,
            selection.TimeoutSeconds,
            buildSeconds,
            nativeDiscoveryAndExecutionSeconds = nativeSeconds,
            totalSeconds = elapsed.Elapsed.TotalSeconds,
            cases,
            omitted = "Unselected tests and families, package/API/architecture checkpoint prerequisites, coverage, mutation, performance and release qualification are not credited."
        }, new JsonSerializerOptions { WriteIndented = true }));
        if (failure is null) { Console.WriteLine($"Passed {cases.Length} selected native cases. Other verification is not credited."); }
        return failure is null ? 0 : 1;

        async Task RunChild(string phase, IEnumerable<string> command)
        {
            string[] commandArguments = command.ToArray();
            File.WriteAllText(Path.Combine(output, phase + "-arguments.json"), JsonSerializer.Serialize(commandArguments));
            ProcessResult result = await ProcessRunner.RunAsync("dotnet", commandArguments, selection.Root, TimeSpan.FromSeconds(selection.TimeoutSeconds));
            File.WriteAllText(Path.Combine(output, phase + ".log"), result.StandardOutput + result.StandardError);
            Console.Write(result.StandardOutput);
            Console.Error.Write(result.StandardError);
            if (result.ExitCode != 0) { throw new InvalidOperationException($"Native {phase} failed with exit code {result.ExitCode}."); }
        }
    }

    internal static NativeCase[] ReadResults(string path, DateTimeOffset started)
    {
        XNamespace ns = "http://microsoft.com/schemas/VisualStudio/TeamTest/2010";
        XElement root = XDocument.Load(path).Root ?? throw new InvalidDataException("Missing native TRX root.");
        Require(root.Name == ns + "TestRun", "Unexpected native TRX schema.");
        XElement summary = root.Element(ns + "ResultSummary") ?? throw new InvalidDataException("Missing native summary.");
        Require((string?)summary.Attribute("outcome") == "Completed", "Native test run did not complete successfully.");
        XElement counters = summary.Element(ns + "Counters") ?? throw new InvalidDataException("Missing native counters.");
        XElement[] results = root.Element(ns + "Results")?.Elements(ns + "UnitTestResult").ToArray() ?? [];
        Require(results.Length > 0, "The filter selected zero native cases.");
        foreach (string name in new[] { "total", "executed", "passed" })
        { Require((int?)counters.Attribute(name) == results.Length, "Native counters disagree with selected cases: " + name); }
        foreach (XAttribute counter in counters.Attributes().Where(item => item.Name.LocalName is not ("total" or "executed" or "passed")))
        { Require(int.TryParse(counter.Value, out int value) && value == 0, "Unexpected native outcome: " + counter.Name); }
        var definitions = root.Element(ns + "TestDefinitions")?.Elements(ns + "UnitTest").ToDictionary(item => Required(item, "id"), StringComparer.Ordinal)
            ?? throw new InvalidDataException("Missing native definitions.");
        var executions = new HashSet<string>(StringComparer.Ordinal);
        return results.Select(result =>
        {
            string id = Required(result, "testId"), execution = Required(result, "executionId");
            Require(executions.Add(execution), "Duplicate native execution ID.");
            Require(Required(result, "outcome") == "Passed", "A selected case failed or was skipped.");
            Require(definitions.ContainsKey(id), "Native case has no definition.");
            XElement definition = definitions[id];
            Require((string?)definition.Element(ns + "Execution")?.Attribute("id") == execution, "Native execution and definition disagree.");
            XElement method = definition.Element(ns + "TestMethod") ?? throw new InvalidDataException("Missing native method.");
            Require(DateTimeOffset.TryParse(Required(result, "startTime"), CultureInfo.InvariantCulture, DateTimeStyles.None, out DateTimeOffset caseStart) && caseStart >= started.AddSeconds(-1), "Stale native case result.");
            return new NativeCase(id, execution, Required(result, "testName"), Required(method, "className") + "." + Required(method, "name"), Required(method, "codeBase"), Required(result, "outcome"));
        }).ToArray();
    }

    private static string Required(XElement element, string name) => !string.IsNullOrWhiteSpace((string?)element.Attribute(name)) ? element.Attribute(name)!.Value : throw new InvalidDataException("Missing native " + name + ".");
    private static void Require(bool condition, string message) { if (!condition) { throw new InvalidDataException(message); } }
}

using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using CIS.TestSupport;

namespace CIS.Verification;

// Shared file/process operations for the existing Type Manager development checks.
internal sealed class TypeManagerVerificationInputs
{
    private readonly Dictionary<string, string> options;
    internal TypeManagerVerificationInputs(string[] arguments, string[] required, string[] optional)
    {
        options = new(StringComparer.Ordinal); var allowed = required.Concat(optional).Append("dotnet").ToHashSet(StringComparer.Ordinal);
        for (int index = 0; index < arguments.Length; index += 2)
        {
            if (index + 1 >= arguments.Length || !arguments[index].StartsWith("--", StringComparison.Ordinal) || !allowed.Contains(arguments[index][2..]) || !options.TryAdd(arguments[index][2..], arguments[index + 1]))
            { throw new ArgumentException("Use each supported named option once, with its value."); }
        }
        if (required.Any(key => !options.ContainsKey(key))) { throw new ArgumentException("Missing required option: " + string.Join(", ", required.Where(key => !options.ContainsKey(key)))); }
    }
    internal string Get(string key) => options.TryGetValue(key, out string? value) ? value : throw new ArgumentException("Missing --" + key);
    internal string? Optional(string key) => options.GetValueOrDefault(key);
    internal string PathOf(string key) => Path.GetFullPath(Get(key));
    internal string Dotnet => Optional("dotnet") ?? "dotnet";
    internal string Language => Path.Combine(PathOf("repo-root"), "implementations", "csharp");
    internal string Output => PathOf("output-root");
    internal void EmptyOutput()
    {
        string root = Output;
        if (Directory.Exists(root) && Directory.EnumerateFileSystemEntries(root).Any()) { throw new InvalidDataException("Use an empty output directory."); }
        Directory.CreateDirectory(root); Directory.CreateDirectory(Path.Combine(root, "logs"));
    }
    internal async Task<ProcessResult> Run(string name, IEnumerable<string> arguments, string? cwd = null, string? expectedError = null, IReadOnlyDictionary<string, string?>? environment = null, TimeSpan? timeout = null, bool requireSuccess = true)
    {
        string[] command = arguments.ToArray();
        ProcessResult child = await ProcessRunner.RunAsync(Dotnet, command, cwd ?? Output, timeout ?? TimeSpan.FromMinutes(4), environment, new UTF8Encoding(false, true));
        string combined = child.StandardOutput + child.StandardError;
        Write(Path.Combine(Output, "logs", name + ".log"), combined);
        WriteJson(Path.Combine(Output, "logs", name + ".process.json"), new JsonObject
        {
            ["pid"] = child.ProcessId,
            ["executable"] = Dotnet,
            ["arguments"] = JsonSerializer.SerializeToNode(command),
            ["exitCode"] = child.ExitCode,
            ["stdoutSha256"] = Digest(Encoding.UTF8.GetBytes(child.StandardOutput)),
            ["stderrSha256"] = Digest(Encoding.UTF8.GetBytes(child.StandardError))
        });
        Require(expectedError is null ? !requireSuccess || child.ExitCode == 0 : child.ExitCode != 0 && combined.Contains(expectedError, StringComparison.Ordinal), name + (expectedError is null ? " failed; inspect its log." : " did not reject for " + expectedError));
        return child;
    }
    internal JsonObject CoreSources() => TreeHashes(Path.Combine(Language, "src", "CIS.Core"), path => path.EndsWith(".cs", StringComparison.Ordinal), sourceOnly: true);
    internal JsonObject CoreProjects() => new(new[] { "src/CIS.Core/CIS.Core.csproj", "global.json", "Directory.Build.props", "Directory.Packages.props", "NuGet.config" }
        .Select(name => new KeyValuePair<string, JsonNode?>(name, JsonValue.Create(Hash(Path.Combine(Language, name))))));
    internal static JsonObject TreeHashes(string root, Func<string, bool>? include = null, bool sourceOnly = false) =>
        new(Directory.EnumerateFiles(root, "*", SearchOption.AllDirectories).Where(path => (!sourceOnly || !Path.GetRelativePath(root, path).Split(Path.DirectorySeparatorChar).Any(part => part is "bin" or "obj")) && (include is null || include(path)))
            .Order(StringComparer.Ordinal).Select(path => new KeyValuePair<string, JsonNode?>(Path.GetRelativePath(root, path).Replace('\\', '/'), JsonValue.Create(Hash(path)))));
    internal static void Copy(string source, string target, string? expectedHash = null)
    {
        string before = Hash(source); Require(expectedHash is null || before == expectedHash, "Input differs from its pin: " + source);
        Directory.CreateDirectory(Path.GetDirectoryName(target)!); File.Copy(source, target, overwrite: true);
        Require(Hash(source) == before && Hash(target) == before, "Input changed while copying: " + source);
    }
    internal static void CopyTree(string source, string target, bool sourceOnly = false)
    {
        foreach (string file in Directory.GetFiles(source, "*", SearchOption.AllDirectories))
        {
            string relative = Path.GetRelativePath(source, file);
            if (sourceOnly && relative.Split(Path.DirectorySeparatorChar).Any(part => part is "bin" or "obj" or "__pycache__")) { continue; }
            Copy(file, Path.Combine(target, relative));
        }
    }
    internal static JsonObject Read(string path) => Read(path, out _);
    internal static JsonObject Read(string path, out string hash)
    {
        byte[] bytes = File.ReadAllBytes(path);
        hash = Digest(bytes);
        return JsonNode.Parse(bytes.AsSpan().StartsWith(Encoding.UTF8.Preamble) ? bytes.AsSpan(Encoding.UTF8.Preamble.Length) : bytes)!.AsObject();
    }
    internal static JsonObject ReadPinned(string path, string expectedHash, string reason)
    {
        byte[] bytes = File.ReadAllBytes(path);
        Require(Digest(bytes) == expectedHash, reason);
        return JsonNode.Parse(bytes.AsSpan().StartsWith(Encoding.UTF8.Preamble) ? bytes.AsSpan(Encoding.UTF8.Preamble.Length) : bytes)!.AsObject();
    }
    internal static string Hash(string path) => Digest(File.ReadAllBytes(path));
    internal static string Digest(ReadOnlySpan<byte> bytes) => Convert.ToHexStringLower(SHA256.HashData(bytes));
    internal static void Write(string path, string text) { Directory.CreateDirectory(Path.GetDirectoryName(path)!); File.WriteAllText(path, text, new UTF8Encoding(false)); }
    internal static void WriteJson(string path, JsonObject value) => Write(path, value.ToJsonString(new JsonSerializerOptions { WriteIndented = true }) + "\n");
    internal static void Require(bool value, string reason) { if (!value) { throw new InvalidDataException(reason); } }
    internal static IReadOnlyDictionary<string, string?> HermeticEnvironment(string root)
    {
        var allowed = new HashSet<string>(["PATH", "SYSTEMROOT", "WINDIR", "COMSPEC", "TEMP", "TMP", "TMPDIR", "HOME", "USERPROFILE", "APPDATA", "LOCALAPPDATA", "PROGRAMFILES", "PROGRAMFILES(X86)", "PROGRAMW6432", "DOTNET_ROOT", "DOTNET_ROOT_X64", "NUMBER_OF_PROCESSORS", "PROCESSOR_ARCHITECTURE"], StringComparer.OrdinalIgnoreCase);
        var result = Environment.GetEnvironmentVariables().Keys.Cast<string>().ToDictionary(key => key, key => allowed.Contains(key) ? Environment.GetEnvironmentVariable(key) : null, OperatingSystem.IsWindows() ? StringComparer.OrdinalIgnoreCase : StringComparer.Ordinal);
        foreach ((string key, string value) in new Dictionary<string, string>
        {
            ["NUGET_PACKAGES"] = Path.Combine(root, "packages"),
            ["NUGET_HTTP_CACHE_PATH"] = Path.Combine(root, "http-cache"),
            ["DOTNET_CLI_HOME"] = Path.Combine(root, "dotnet-home"),
            ["DOTNET_CLI_TELEMETRY_OPTOUT"] = "1",
            ["MSBUILDDISABLENODEREUSE"] = "1",
            ["DOTNET_GENERATE_ASPNET_CERTIFICATE"] = "false",
            ["DOTNET_ADD_GLOBAL_TOOLS_TO_PATH"] = "false",
            ["DOTNET_CLI_WORKLOAD_UPDATE_NOTIFY_DISABLE"] = "true",
            ["DOTNET_NOLOGO"] = "1"
        }) { result[key] = value; }
        return result;
    }

}

using System.IO.Compression;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Xml.Linq;
using static CIS.Verification.TypeManagerVerificationInputs;

namespace CIS.Verification;

// Real first-publication controls; an empty publication ledger is never historical replay credit.
internal static class FirstReleaseCompatibility
{
    internal static async Task<int> RunAsync(string[] args)
    {
        var input = new TypeManagerVerificationInputs(args,
            ["repo-root", "candidate-package", "dependency-directory", "output-root"], ["frozen-fixtures", "fixture-directory"]);
        input.EmptyOutput();
        string root = input.Output, repo = input.PathOf("repo-root"), package = input.PathOf("candidate-package");
        string dependencies = input.PathOf("dependency-directory"), language = input.Language;
        string ledgerPath = Path.Combine(repo, "compatibility/csharp/publications/ledger.json");
        JsonObject ledger = Read(ledgerPath), policy = Read(Path.Combine(language, "eng/toolchain.json"));
        Require(ledger["publications"]!.AsArray().Count == 0, "Published history requires cumulative replay; first-release controls cannot replace it.");
        Require((string?)policy["sdk"] == "10.0.401" && (string?)policy["targetRuntime"] == "10.0.12", "Requalify consumer settings for changed toolchain pins.");
        string fixture = input.Optional("fixture-directory") is { } suppliedFixture ? Path.GetFullPath(suppliedFixture) : Path.Combine(language, "verification/compatibility/first-release");
        string packagePin = Hash(package), ledgerPin = Hash(ledgerPath);
        JsonObject sources = input.CoreSources(), projects = input.CoreProjects();
        var report = new JsonObject
        {
            ["schema"] = "cis.first-release-compatibility/v1",
            ["qualified"] = false,
            ["historyStatus"] = "NoBaselineForIdentity",
            ["historicalVersionsReplayed"] = 0,
            ["scope"] = "Exact candidate package and first-release positive/negative controls, not released historical replay",
            ["candidatePackageSha256"] = packagePin,
            ["ledgerSha256"] = ledgerPin,
            ["verifierSha256"] = Hash(typeof(FirstReleaseCompatibility).Assembly.Location),
            ["coreSourceInputs"] = sources.DeepClone(),
            ["results"] = new JsonArray()
        };
        string reportPath = Path.Combine(root, "results.json");
        var environment = new Dictionary<string, string?>
        {
            ["MSBUILDDISABLENODEREUSE"] = "1",
            ["UseSharedCompilation"] = "false",
            ["DOTNET_CLI_TELEMETRY_OPTOUT"] = "1",
            ["GIT_CEILING_DIRECTORIES"] = root
        };
        foreach (string key in Environment.GetEnvironmentVariables().Keys.Cast<string>().Where(key => key.StartsWith("CORE_", StringComparison.OrdinalIgnoreCase) || key.StartsWith("DD_", StringComparison.OrdinalIgnoreCase)))
        { environment[key] = null; }
        void Passed(string name, JsonNode? observation = null) => report["results"]!.AsArray().Add(new JsonObject { ["id"] = name, ["passed"] = true, ["observation"] = observation });
        try
        {
            Require((await input.Run("sdk", ["--version"], language)).StandardOutput.Trim() == (string?)policy["sdk"], "Wrong SDK selected.");
            string feed = Path.Combine(root, "feed"); Directory.CreateDirectory(feed);
            using var zip = ZipFile.OpenRead(package);
            ZipArchiveEntry coreEntry = zip.Entries.Single(entry => entry.FullName == "lib/net10.0/CIS.Core.dll");
            string expectedCore = Path.Combine(root, "references/CIS.Core.dll");
            Directory.CreateDirectory(Path.GetDirectoryName(expectedCore)!);
            coreEntry.ExtractToFile(expectedCore);
            string corePin = Hash(expectedCore);
            Require(corePin == Hash(Path.Combine(dependencies, "CIS.Core.dll")), "Package and selected built dependency directory differ.");
            report["candidateCoreSha256"] = corePin;
            Copy(package, Path.Combine(feed, "CIS.Core.0.1.0-dev.1.nupkg"), packagePin);
            JsonObject assets = Read(Path.Combine(language, "src/CIS.Core/obj/project.assets.json"));
            string[] cacheRoots = assets["packageFolders"]!.AsObject().Select(row => row.Key).ToArray();
            JsonObject approved = Read(Path.Combine(language, "eng/runtime-dependencies.json"));
            foreach (JsonNode? dependency in approved["packages"]!.AsArray())
            {
                string id = dependency!["id"]!.GetValue<string>(), version = dependency["version"]!.GetValue<string>();
                string relative = Path.Combine(id.ToLowerInvariant(), version, id.ToLowerInvariant() + "." + version + ".nupkg");
                string nupkg = cacheRoots.Select(cache => Path.Combine(cache, relative)).Single(File.Exists);
                Copy(nupkg, Path.Combine(feed, Path.GetFileName(nupkg)));
                Copy(Path.Combine(dependencies, id + ".dll"), Path.Combine(root, "references", id + ".dll"));
            }
            string original = Path.Combine(root, "original"); Directory.CreateDirectory(original);
            Copy(Path.Combine(fixture, "Program.cs"), Path.Combine(original, "Program.cs"));
            Copy(Path.Combine(fixture, "Consumer.csproj.template"), Path.Combine(original, "Consumer.csproj"));
            var originalPins = TreeHashes(original);
            await BuildConsumer("source", original, feed, expectedError: null);
            string compiled = Path.Combine(original, "bin/Release/net10.0");
            await Execute("source", compiled, corePin);
            string frozen = Path.Combine(root, "frozen");
            string? prior = input.Optional("frozen-fixtures");
            if (prior is null) { CopyTree(compiled, frozen); }
            else
            {
                JsonObject previous = Read(Path.Combine(prior, "results.json"));
                Require((bool?)previous["qualified"] == true && (string?)previous["candidatePackageSha256"] == packagePin, "Cross-lane frozen fixtures identify another or incomplete candidate.");
                CopyTree(Path.Combine(prior, "frozen"), frozen);
                Require(JsonNode.DeepEquals(TreeHashes(frozen), previous["frozenFiles"]), "Cross-lane frozen consumer bytes changed.");
            }
            JsonObject frozenPins = TreeHashes(frozen); report["frozenFiles"] = frozenPins.DeepClone();
            foreach (string scenario in new[] { "CoreReplacement", "CompleteUpgrade" })
            {
                string directory = Path.Combine(root, scenario); CopyTree(frozen, directory);
                Copy(expectedCore, Path.Combine(directory, "CIS.Core.dll"), corePin);
                await Execute(scenario, directory, corePin);
            }
            await input.Run("tool-restore", ["tool", "restore", "--configfile", "eng/Tools.NuGet.config"], language);
            string toolVersion = policy["tools"]!.AsArray().Single(node => (string?)node!["id"] == "Microsoft.DotNet.ApiCompat.Tool")!["version"]!.GetValue<string>();
            string api = cacheRoots.Select(cache => Path.Combine(cache, "microsoft.dotnet.apicompat.tool", toolVersion, "tools/net8.0/any/Microsoft.DotNet.ApiCompat.Tool.dll")).Single(File.Exists);
            string netRoot = (await input.Run("reference-pack-root", ["msbuild", Path.Combine(language, "src/CIS.Core/CIS.Core.csproj"), "-nologo", "-getProperty:NetCoreRoot"], language)).StandardOutput.Trim();
            string referencePack = Path.Combine(netRoot, "packs/Microsoft.NETCore.App.Ref/10.0.12/ref/net10.0");
            Require(Directory.Exists(referencePack), "The pinned .NET 10 reference pack is missing.");
            JsonObject referencePins = TreeHashes(referencePack, path => path.EndsWith(".dll", StringComparison.Ordinal));
            Require(referencePins.Count > 0, "Reference pack has no assemblies.");
            report["apiReferenceInputs"] = referencePins.DeepClone();
            await Api("api-self", expectedCore, negative: false);
            string controlled = Path.Combine(root, "controlled-source");
            string controlledLanguage = Path.Combine(controlled, "implementations/csharp");
            CopyTree(language, controlledLanguage, sourceOnly: true);
            Copy(Path.Combine(repo, "README.md"), Path.Combine(controlled, "README.md"));
            string controlledCore = Path.Combine(controlledLanguage, "src/CIS.Core/CIS.Core.csproj");
            string addition = Path.Combine(controlledLanguage, "src/CIS.Core/Logging/QualificationAddition.cs");
            Write(addition, "namespace CIS.Logging; public sealed partial class CoreLogger { /// <summary>Qualification-only additive API control.</summary>\n public bool QualificationAddition() => true; }\n");
            await input.Run("additive-build", ["build", controlledCore, "-c", "Release", "-m:1", "-p:RestoreLockedMode=true"], language, environment: environment);
            string changedCore = Path.Combine(controlledLanguage, "src/CIS.Core/bin/Release/net10.0/CIS.Core.dll");
            await Api("api-additive", changedCore, negative: false);
            string changed = Path.Combine(controlledLanguage, "src/CIS.Core/Logging/CoreLogger.Interpolation.cs");
            const string signature = "public LogWriteResult Info(ref LogInterpolatedStringHandler message, IReadOnlyDictionary<string, LogValue> values)";
            string text = File.ReadAllText(changed);
            Require(text.Split(signature, StringSplitOptions.None).Length == 2, "Expected exactly one controlled overload.");
            Write(changed, text.Replace(signature, signature.Replace(" Info(", " RemovedInfo(", StringComparison.Ordinal), StringComparison.Ordinal));
            await input.Run("breaking-build", ["build", controlledCore, "-c", "Release", "-m:1", "--no-restore"], language, environment: environment);
            await Api("api-breaking", changedCore, negative: true);
            string badFeed = Path.Combine(root, "breaking-feed");
            foreach (string file in Directory.GetFiles(feed).Where(path => !Path.GetFileName(path).StartsWith("CIS.Core.", StringComparison.OrdinalIgnoreCase))) { Copy(file, Path.Combine(badFeed, Path.GetFileName(file))); }
            await input.Run("breaking-pack", ["pack", controlledCore, "-c", "Release", "--no-build", "--no-restore", "-o", badFeed], language, environment: environment);
            string badSource = Path.Combine(root, "breaking-source");
            foreach ((string path, JsonNode? pin) in originalPins) { Copy(Path.Combine(original, path), Path.Combine(badSource, path), (string)pin!); }
            await BuildConsumer("source-breaking", badSource, badFeed, "CS1503");
            Passed("source-breaking");
            string badBinary = Path.Combine(root, "breaking-binary"); CopyTree(frozen, badBinary);
            Copy(changedCore, Path.Combine(badBinary, "CIS.Core.dll"));
            await input.Run("binary-breaking", ["exec", "--fx-version", "10.0.12", "--roll-forward", "Disable", Path.Combine(badBinary, "CIS.FirstRelease.Consumer.dll")], badBinary, expectedError: "MissingMethodException", environment: environment);
            Passed("binary-breaking");
            Require(JsonNode.DeepEquals(frozenPins, TreeHashes(frozen)), "Frozen consumer bytes changed during controls.");
            foreach ((string path, JsonNode? pin) in originalPins) { Require(Hash(Path.Combine(original, path)) == (string?)pin, "Original consumer source changed."); }
            Require(Hash(package) == packagePin && Hash(ledgerPath) == ledgerPin && JsonNode.DeepEquals(sources, input.CoreSources()) && JsonNode.DeepEquals(projects, input.CoreProjects()), "Candidate or source inputs changed during qualification.");
            Require(JsonNode.DeepEquals(referencePins, TreeHashes(referencePack, path => path.EndsWith(".dll", StringComparison.Ordinal))), "API reference pack changed during qualification.");
            Require(Hash(Path.Combine(fixture, "Program.cs")) == (string?)originalPins["Program.cs"] && Hash(Path.Combine(fixture, "Consumer.csproj.template")) == (string?)originalPins["Consumer.csproj"], "Supplied consumer fixture changed during qualification.");
            report["qualified"] = true;
            return 0;

            async Task BuildConsumer(string name, string directory, string packageFeed, string? expectedError)
            {
                string config = Path.Combine(root, name + ".NuGet.config");
                new XDocument(new XElement("configuration", new XElement("packageSources", new XElement("clear"), new XElement("add", new XAttribute("key", "candidate"), new XAttribute("value", packageFeed))), new XElement("fallbackPackageFolders", new XElement("clear")), new XElement("auditSources", new XElement("clear")))).Save(config);
                string project = Path.Combine(directory, "Consumer.csproj");
                var childEnvironment = new Dictionary<string, string?>(environment) { ["NUGET_PACKAGES"] = Path.Combine(root, name + "-packages"), ["NUGET_HTTP_CACHE_PATH"] = Path.Combine(root, name + "-http") };
                await input.Run(name + "-restore", ["restore", project, "--configfile", config, "--packages", childEnvironment["NUGET_PACKAGES"]!, "-p:NuGetAudit=false"], language, environment: childEnvironment);
                await input.Run(name + "-build", ["build", project, "-c", "Release", "--no-restore", "-m:1", "-p:NuGetAudit=false"], language, expectedError: expectedError, environment: childEnvironment);
            }
            async Task Execute(string name, string directory, string pin)
            {
                var result = await input.Run(name, ["exec", "--fx-version", "10.0.12", "--roll-forward", "Disable", Path.Combine(directory, "CIS.FirstRelease.Consumer.dll")], directory, environment: environment);
                JsonObject observed = JsonNode.Parse(result.StandardOutput)!.AsObject();
                Require((bool?)observed["succeeded"] == true && (string?)observed["coreSha256"] == pin && (string?)observed["runtime"] == "10.0.12" && (int?)observed["records"] == 2, "Consumer observation differs from candidate/runtime/behavior.");
                Passed(name, observed);
            }
            async Task Api(string name, string right, bool negative)
            {
                string references = Path.Combine(root, "references") + "," + referencePack;
                var result = await input.Run(name, ["exec", "--fx-version", "8.0.31", "--roll-forward", "Disable", api, "--left", expectedCore, "--right", right, "--enable-rule-attributes-must-match", "--enable-rule-cannot-change-parameter-name", "--left-assembly-references", references, "--right-assembly-references", references], language, expectedError: negative ? "CP0002" : null, environment: environment);
                Require(!(result.StandardOutput + result.StandardError).Contains("Could not resolve reference", StringComparison.Ordinal), "API comparison has unresolved references.");
                Require(!negative || (result.StandardOutput + result.StandardError).Contains("CoreLogger.Info", StringComparison.Ordinal), "API control did not identify the removed logger overload.");
                Passed(name);
            }
        }
        catch (Exception error) { report["error"] = error.Message; throw; }
        finally { WriteJson(reportPath, report); }
    }
}

using System.Globalization;
using System.Security.Cryptography;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Text.RegularExpressions;
using System.Xml;
using System.Xml.Linq;
using CIS.TestSupport;

namespace CIS.Verification;

// Cobertura identifies branch counts, not individual branch identities. Never sum hits across reports.
internal static class ShippingCoverage
{
    private sealed record Source(string Path, string Sha256, string? NonExecutableReason);
    private readonly record struct Identity(string Path, string Class, long Line);
    private readonly record struct Point(bool Hit, long Covered, long Total);
    private sealed record AssemblyData(Dictionary<string, Source> Sources, Dictionary<Identity, Point> Points);

    internal static async Task<int> RunAsync(string[] args)
    {
        try
        {
            if (args.Length < 3) { throw new ArgumentException("Usage: shipping-coverage <language-root> <new-output.json> <results-directory> [...]"); }
            string output = Path.GetFullPath(args[1]);
            if (File.Exists(output)) { throw new IOException("Use a new immutable output path."); }
            JsonObject result = await SummarizeAsync(Path.GetFullPath(args[0]), args[2..].Select(Path.GetFullPath).ToArray());
            using (var stream = new FileStream(output, FileMode.CreateNew, FileAccess.Write, FileShare.None))
            {
                await JsonSerializer.SerializeAsync(stream, result, new JsonSerializerOptions { WriteIndented = true });
            }
            Console.WriteLine(new JsonObject { ["aggregate"] = result["aggregate"]!.DeepClone(), ["qualified"] = result["qualified"]!.DeepClone() }.ToJsonString());
            return result["qualified"]!.GetValue<bool>() ? 0 : 2;
        }
        catch (Exception exception) when (exception is IOException or InvalidDataException or UnauthorizedAccessException or ArgumentException or InvalidOperationException or JsonException or XmlException or FormatException or OverflowException or TimeoutException)
        {
            Console.Error.WriteLine("Shipping coverage failed: " + exception.Message);
            return 1;
        }
    }

    internal static async Task<JsonObject> SummarizeAsync(string language, IReadOnlyList<string> directories, Func<string, Task<string>>? evaluate = null)
    {
        if (directories.Count == 0) { throw new InvalidDataException("At least one native report is required."); }
        language = Path.GetFullPath(language);
        string policyPath = Path.Combine(language, "verification/coverage/shipping.json");
        JsonObject policy = JsonNode.Parse(File.ReadAllText(policyPath))!.AsObject();
        double lineMinimum = policy["minimumLineRate"]!.GetValue<double>();
        double branchMinimum = policy["minimumBranchRate"]!.GetValue<double>();
        if (!double.IsFinite(lineMinimum) || !double.IsFinite(branchMinimum) || lineMinimum is < 0 or > 1 || branchMinimum is < 0 or > 1)
        { throw new InvalidDataException("Invalid coverage thresholds."); }
        var owners = new Dictionary<string, string>(StringComparer.Ordinal);
        var assemblies = new Dictionary<string, AssemblyData>(StringComparer.Ordinal);
        foreach (JsonNode? entry in policy["assemblies"]!.AsArray())
        {
            string name = entry!["name"]!.GetValue<string>();
            string sourceRoot = Contained(language, entry["sourceRoot"]!.GetValue<string>());
            JsonObject nonExecutable = entry["nonExecutable"]!.AsObject();
            var sources = new Dictionary<string, Source>(StringComparer.Ordinal);
            var relativeFiles = new HashSet<string>(StringComparer.Ordinal);
            foreach (string file in Directory.EnumerateFiles(sourceRoot, "*.cs", SearchOption.AllDirectories).Order(StringComparer.Ordinal))
            {
                string relative = Slashes(Path.GetRelativePath(sourceRoot, file));
                if (Generated(relative)) { continue; }
                relativeFiles.Add(relative);
                string key = SourceKey(language, file);
                string? reason = nonExecutable[relative]?.GetValue<string>();
                sources.Add(key, new Source(key, Hash(file), reason));
                owners.Add(key, name);
            }
            if (nonExecutable.Any(item => !relativeFiles.Contains(item.Key)))
            { throw new InvalidDataException("Non-executable inventory names a missing source."); }
            string project = entry["project"]!.GetValue<string>();
            _ = Contained(language, project);
            string evaluated;
            if (evaluate is not null) { evaluated = await evaluate(project); }
            else
            {
                ProcessResult child = await ProcessRunner.RunAsync("dotnet", ["msbuild", project, "-getItem:Compile", "-p:Configuration=Release", "-p:TargetFramework=net10.0", "-nologo"], language, TimeSpan.FromSeconds(60));
                if (child.ExitCode != 0) { throw new InvalidDataException("Compile inventory evaluation failed: " + project + "\n" + child.StandardError); }
                evaluated = child.StandardOutput;
            }
            JsonArray items = JsonNode.Parse(evaluated)!["Items"]!["Compile"]!.AsArray();
            var compiled = new HashSet<string>(StringComparer.Ordinal);
            foreach (JsonNode? item in items)
            {
                string file = item!["FullPath"]!.GetValue<string>();
                if (!Generated(Slashes(file))) { compiled.Add(SourceKey(language, file)); }
            }
            if (!compiled.SetEquals(sources.Keys))
            { throw new InvalidDataException("Evaluated Compile inventory differs from the declared source scope: " + name); }
            assemblies.Add(name, new AssemblyData(sources, []));
        }

        var reports = new JsonArray();
        foreach (string directory in directories)
        {
            string trx = Path.Combine(directory, "report.trx");
            XDocument test = ReadXml(trx);
            XElement[] counters = test.Descendants().Where(element => element.Name.LocalName == "Counters").ToArray();
            if (counters.Length != 1 || Number(counters[0], "total") <= 0 || Number(counters[0], "total") != Number(counters[0], "passed"))
            { throw new InvalidDataException("Missing, failed or skipped test results: " + trx); }
            string[] attached = test.Descendants().Where(element => element.Name.LocalName == "A")
                .Select(element => (string?)element.Attribute("href")).OfType<string>().Where(href => href.EndsWith(".cobertura.xml", StringComparison.Ordinal)).ToArray();
            if (attached.Length != 1) { throw new InvalidDataException("Expected one native Microsoft Cobertura attachment: " + trx); }
            string filename = Slashes(attached[0]).Split('/')[^1];
            string[] matches = Directory.EnumerateFiles(directory, "*", SearchOption.AllDirectories)
                .Where(file => Path.GetFileName(file) == filename).Order(StringComparer.Ordinal).ToArray();
            if (matches.Length == 0 || matches.Select(Hash).Distinct(StringComparer.Ordinal).Count() != 1)
            { throw new InvalidDataException("Absent or conflicting native attachment."); }
            string report = matches[0];
            XDocument xml = ReadXml(report);
            var local = new HashSet<(string Assembly, Identity Identity)>();
            long lc = 0, lt = 0, bc = 0, bt = 0;
            foreach (XElement package in xml.Root!.Elements("packages").Elements("package"))
            {
                string name = Required(package, "name");
                if (!assemblies.TryGetValue(name, out AssemblyData? assembly))
                { throw new InvalidDataException("Unexpected shipping assembly: " + name); }
                foreach (XElement cls in package.Elements("classes").Elements("class"))
                {
                    string nativePath = Slashes(Required(cls, "filename"));
                    const string marker = "/implementations/csharp/";
                    int position = nativePath.LastIndexOf(marker, StringComparison.Ordinal);
                    if (position < 0) { throw new InvalidDataException("Unmapped source: " + nativePath); }
                    string path = "implementations/csharp/" + nativePath[(position + marker.Length)..];
                    if (!owners.TryGetValue(path, out string? owner) || owner != name)
                    { throw new InvalidDataException("Source outside inventoried shipping scope: " + path); }
                    if (!string.IsNullOrEmpty(assembly.Sources[path].NonExecutableReason))
                    { throw new InvalidDataException("A declared non-executable source has native sequence points: " + path); }
                    foreach (XElement line in cls.Elements("lines").Elements("line"))
                    {
                        var key = new Identity(path, Required(cls, "name"), Number(line, "number"));
                        if (!local.Add((name, key))) { throw new InvalidDataException("Duplicate native class/source/line identity."); }
                        long hits = Number(line, "hits");
                        if (key.Line <= 0 || hits < 0) { throw new InvalidDataException("Invalid native line observation."); }
                        long covered = 0, total = 0;
                        if (string.Equals((string?)line.Attribute("branch"), "true", StringComparison.OrdinalIgnoreCase))
                        {
                            Match match = Regex.Match((string?)line.Attribute("condition-coverage") ?? "", @"^.*\(([0-9]+)/([0-9]+)\)$", RegexOptions.CultureInvariant, TimeSpan.FromSeconds(1));
                            if (!match.Success) { throw new InvalidDataException("Missing native branch counts."); }
                            covered = long.Parse(match.Groups[1].Value, CultureInfo.InvariantCulture);
                            total = long.Parse(match.Groups[2].Value, CultureInfo.InvariantCulture);
                            if (total <= 0 || covered > total) { throw new InvalidDataException("Invalid native branch counts."); }
                        }
                        bool previousExists = assembly.Points.TryGetValue(key, out Point previous);
                        if (previousExists && previous.Total != total) { throw new InvalidDataException("Branch denominator drift: " + key); }
                        assembly.Points[key] = new Point(hits > 0 || previous.Hit, Math.Max(covered, previous.Covered), total);
                        checked { lc += hits > 0 ? 1 : 0; lt++; bc += covered; bt += total; }
                    }
                }
            }
            long[] totals = [lc, lt, bc, bt];
            long[] native = [Number(xml.Root!, "lines-covered"), Number(xml.Root!, "lines-valid"), Number(xml.Root!, "branches-covered"), Number(xml.Root!, "branches-valid")];
            if (!totals.SequenceEqual(native)) { throw new InvalidDataException("Parsed denominator does not equal the native report totals."); }
            reports.Add(new JsonObject
            {
                ["trx"] = trx,
                ["trxSha256"] = Hash(trx),
                ["cobertura"] = report,
                ["coberturaSha256"] = Hash(report),
                ["testsPassed"] = Number(counters[0], "passed"),
                ["nativeTotals"] = JsonSerializer.SerializeToNode(totals)
            });
        }

        JsonObject Counts(IEnumerable<Point> values)
        {
            Point[] points = values.ToArray();
            long lc = points.LongCount(point => point.Hit), lt = points.LongLength, bc = points.Sum(point => point.Covered), bt = points.Sum(point => point.Total);
            return new JsonObject
            {
                ["linesCovered"] = lc,
                ["linesTotal"] = lt,
                ["branchesCoveredLowerBound"] = bc,
                ["branchesTotal"] = bt,
                ["lineRate"] = lt > 0 ? (double)lc / lt : null,
                ["branchRateLowerBound"] = bt > 0 ? (double)bc / bt : null,
                ["thresholdPassed"] = lt > 0 && bt > 0 && lc >= lineMinimum * lt && bc >= branchMinimum * bt
            };
        }
        var output = new JsonArray();
        var aggregate = new List<Point>();
        foreach ((string name, AssemblyData assembly) in assemblies)
        {
            var files = new JsonArray();
            foreach ((string path, Source source) in assembly.Sources)
            {
                KeyValuePair<Identity, Point>[] points = assembly.Points.Where(point => point.Key.Path == path).ToArray();
                if (points.Length == 0 && string.IsNullOrEmpty(source.NonExecutableReason))
                { throw new InvalidDataException("Unmeasured executable source: " + path); }
                JsonObject file = Counts(points.Select(point => point.Value));
                file["path"] = source.Path; file["sha256"] = source.Sha256; file["nonExecutableReason"] = source.NonExecutableReason;
                file["uncoveredLines"] = JsonSerializer.SerializeToNode(points.Where(point => !point.Value.Hit).Select(point => point.Key.Line).Distinct().Order());
                file["partiallyCoveredBranchLines"] = JsonSerializer.SerializeToNode(points.Where(point => point.Value.Covered < point.Value.Total).Select(point => point.Key.Line).Distinct().Order());
                files.Add(file);
            }
            if (assembly.Points.Values.Sum(point => point.Total) == 0) { throw new InvalidDataException("Assembly has no native branch denominator: " + name); }
            JsonObject item = Counts(assembly.Points.Values);
            item["assembly"] = name; item["sources"] = files; output.Add(item);
            aggregate.AddRange(assembly.Points.Values);
        }
        if (!assemblies.TryGetValue("CIS.Core", out AssemblyData? core)) { throw new InvalidDataException("Missing CIS.Core calibration assembly."); }
        Point[] calibration = core.Points.Where(point => point.Key.Path.EndsWith("/SeverityTokenParser.cs", StringComparison.Ordinal)).Select(point => point.Value).ToArray();
        if (calibration.Length == 0 || calibration.Sum(point => point.Total) == 0 || calibration.Sum(point => point.Covered) == 0)
        { throw new InvalidDataException("Known branching fixture has no observed branches."); }
        return new JsonObject
        {
            ["schema"] = "cis.csharp.shipping-coverage-observation/v1",
            ["policySha256"] = Hash(policyPath),
            ["aggregation"] = policy["aggregation"]!.DeepClone(),
            ["exclusions"] = policy["exclusions"]!.DeepClone(),
            ["reports"] = reports,
            ["assemblies"] = output,
            ["aggregate"] = Counts(aggregate),
            ["qualified"] = output.All(item => item!["thresholdPassed"]!.GetValue<bool>()),
            ["branchCalibration"] = Counts(calibration)
        };
    }

    private static string Contained(string root, string relative)
    {
        string path = Path.GetFullPath(relative, root);
        string check = Path.GetRelativePath(root, path);
        if (Path.IsPathRooted(check) || check == ".." || check.StartsWith(".." + Path.DirectorySeparatorChar, StringComparison.Ordinal))
        { throw new InvalidDataException("Coverage path escapes the language root."); }
        return path;
    }
    private static string SourceKey(string language, string path) => "implementations/csharp/" + Slashes(Path.GetRelativePath(language, Contained(language, path)));
    private static bool Generated(string path) => path.Split('/').Any(part => part is "bin" or "obj");
    private static string Slashes(string path) => path.Replace('\\', '/');
    private static string Hash(string path) => Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(path)));
    private static string Required(XElement element, string name) => (string?)element.Attribute(name) ?? throw new InvalidDataException("Missing XML attribute: " + name);
    private static long Number(XElement element, string name) => long.Parse(Required(element, name), CultureInfo.InvariantCulture);
    private static XDocument ReadXml(string path)
    {
        using XmlReader reader = XmlReader.Create(path, new XmlReaderSettings { DtdProcessing = DtdProcessing.Prohibit, XmlResolver = null });
        return XDocument.Load(reader);
    }
}

