        {
            bool actualInteger = actual.ToJsonString().IndexOfAny(['.', 'e', 'E']) < 0;
            bool expectedInteger = expected.ToJsonString().IndexOfAny(['.', 'e', 'E']) < 0;
            return actualInteger == expectedInteger && JsonNode.DeepEquals(actual, expected);
