    internal string ReadMessage()
    {
        MessageReads++;
        if (FailIfRead)
        {
            throw new InvalidOperationException("Omitted exception accessor must not be read.");
        }
        return Message!;
    }

    internal string? ReadStack()
    {
        StackReads++;
        if (FailIfRead)
        {
            throw new InvalidOperationException("Omitted exception accessor must not be read.");
        }
        return Stack;
    }

    internal void Reset()
    {
        MessageReads = 0;
        StackReads = 0;
    }
}

